/*
 * glossary.js: every term the handbook defines, keyed by a stable id.
 *
 * Used by: the hover card on any `.term` / `dfn.term` element, the glossary
 * page, the search index, and the structure tests.
 *
 * Fields:
 *   term  display name
 *   aka   other names readers will meet in engines, docs or AI output
 *   def   one or two plain sentences; no term used here should need its own
 *         lookup to make sense
 *   ch    the chapter that teaches it ("4.2"). The tests use this to enforce
 *         "no term before its chapter": a page that mentions a term taught
 *         later must mark that mention data-forward.
 *
 * Keep ids lowercase-hyphenated; they are also the glossary page anchors.
 */
(function () {
  "use strict";

  var HB = (window.HB = window.HB || {});

  HB.glossary = {
    "acceleration-structure": { term: "Acceleration structure", aka: ["AS","ray tracing acceleration structure","RayTracingAccelerationStructure"], def: "A structure that groups a scene's triangles so a ray can skip almost all of them. Ray tracing APIs build it from meshes and instances; GPUs walk it as a tree of boxes.", ch: "8.6" },
    "aces": { term: "ACES", aka: ["Academy Color Encoding System","ACES filmic","ACES fit","RRT","ODT","ACES 2"], def: "A colour management standard from film production whose output transforms include a tone curve. Games often use fitted approximations of the ACES 1 curve, which shifts very bright saturated colours towards yellow and white.", ch: "9.1" },
    "actor": { term: "Actor", aka: ["AActor"], def: "Unreal Engine's object: anything that can be placed in a level. Its components give it meshes, collision, lights and behaviour, and its root component gives it a position.", ch: "2.3" },
    "adaptive-probe-volumes": { term: "Adaptive Probe Volumes", aka: ["APV","probe volumes","Probe Volume","Baking Set"], def: "Unity's system in URP and HDRP that places light probes automatically in bricks of 64, closer together where there is more geometry, and samples them per pixel rather than per object.", ch: "8.2" },
    "additive-blending": { term: "Additive blending", aka: ["additive","add blend"], def: "Adding a new colour to the colour already in the image, so it can only brighten. Used for fire, sparks and glows; the result is the same in any draw order.", ch: "5.5" },
    "aerial-perspective": { term: "Aerial perspective", aka: ["atmospheric perspective","distance haze","Aerial Perspective View Distance Scale"], def: "Distant objects losing contrast and taking on the sky's colour because of the air between them and the viewer. Renderers apply it from the sky model so terrain fades into the horizon instead of ending in a line.", ch: "9.5" },
    "agx": { term: "AgX", aka: ["AgX view transform","AgX tonemapper"], def: "A tone mapping transform by Troy Sobotka that mixes a little of each channel into the others and compresses in log space, so bright saturated colours fade towards white with little hue shift. Blender's default view transform since 4.0.", ch: "9.1" },
    "ai-denoiser": { term: "AI denoiser", aka: ["neural denoiser","ML denoiser","Open Image Denoise","OIDN","OptiX denoiser","FSR Ray Regeneration"], def: "A denoiser that is a neural network trained on pairs of noisy and clean images. Offline renderers use one on final frames; real-time versions run every frame.", ch: "8.7" },
    "albedo": { term: "Albedo", aka: ["base colour","diffuse colour"], def: "The colour a surface reflects under white light, with no lighting or shadow baked in. Light-coloured surfaces bounce more light around a scene.", ch: "6.5" },
    "albedo-range": { term: "Plausible albedo range", aka: ["PBR validation","albedo chart","physically plausible values","PBR safe range"], def: "The range of base colours real non-metals have, from about 2% (charcoal) to 81% (fresh snow) of light reflected, which validation tools check. Adobe's Substance guide puts the limits at sRGB 30 to 50 for the darkest and 240 for the brightest.", ch: "6.5" },
    "aliasing": { term: "Aliasing", aka: ["sampling artefacts","jaggies and shimmer"], def: "False detail that appears when an image is sampled too sparsely for what it shows: stair-stepped edges, broken thin lines, moiré and sparkle. In motion it crawls and flickers.", ch: "9.2" },
    "alpha": { term: "Alpha", aka: ["feature complete"], def: "The milestone at which every feature is in the game and playable from start to finish, after which no new features are started. Studios define the exact criteria differently.", ch: "1.1" },
    "alpha-blending": { term: "Alpha blending", aka: ["alpha blend","translucent","transparent","over"], def: "Mixing a new colour over the existing one in proportion to its alpha: alpha × new + (1 − alpha) × old. The result depends on draw order, so blended surfaces must be sorted back to front.", ch: "5.5" },
    "alpha-test": { term: "Alpha test", aka: ["alpha cutout","alpha clip","alpha clipping","alpha scissor","masked"], def: "Discarding pixels whose alpha falls below a threshold, typically 0.5, and drawing the rest fully opaque. Cut-outs such as leaves and fences can then write depth and need no sorting.", ch: "5.5" },
    "alpha-tested-foliage": { term: "Alpha-tested foliage", aka: ["cut-out foliage","masked foliage","alpha cards","foliage cards"], def: "Leaves and grass drawn as flat cards whose texture alpha cuts out the shape. The pixel shader must run across the whole card to decide what to keep, so dense foliage is costly to shade.", ch: "5.4" },
    "alu-bound": { term: "ALU-bound", aka: ["compute-bound","math-bound","shader-bound","arithmetic-bound"], def: "A GPU pass limited by the arithmetic in its shaders, such as long material graphs or many lights per pixel. Only less maths per pixel or per thread makes it faster.", ch: "11.2" },
    "ambient-occlusion": { term: "Ambient occlusion", aka: ["AO"], def: "How much of the surrounding sky or environment a point can see. Creases, corners and contact points see less of it, so they receive less ambient light and look darker.", ch: "8.3" },
    "ambient-term": { term: "Ambient term", aka: ["ambient","flat ambient","ambient colour"], def: "A constant amount of light added to every point to stand in for light bouncing around a scene. It has no direction, so it flattens shapes; modern engines take this light from the sky, probes and global illumination instead.", ch: "7.2" },
    "animation-compression": { term: "Animation compression", aka: ["keyframe reduction","bone compression","curve compression"], def: "Shrinking stored animation by dropping keys that interpolation can rebuild and storing the rest with fewer bits, trading memory for small errors in the motion.", ch: "4.6" },
    "animation-system": { term: "Animation system", aka: ["animation","Animator","Animation Blueprint","AnimationTree"], def: "The engine system that plays, blends and adjusts animations, such as a character's walk and run cycles, and poses the skeleton every frame.", ch: "2.1" },
    "anisotropic-filtering": { term: "Anisotropic filtering", aka: ["AF","aniso","16× AF","Aniso Level"], def: "Taking several samples along the long axis of a pixel's stretched footprint, so surfaces seen at a grazing angle, such as floors and roads, stay sharp. The level, such as 16×, caps the number of samples.", ch: "6.2" },
    "anti-aliasing": { term: "Anti-aliasing", aka: ["AA","antialiasing","Anti-Aliasing Method"], def: "Any technique that brings each pixel closer to the true share of what it covers, by taking more samples, smoothing the finished image, or blending samples from several frames.", ch: "9.2" },
    "anti-lag": { term: "AMD Anti-Lag 2", aka: ["Anti-Lag","Radeon Anti-Lag 2","Anti-Lag 2"], def: "AMD's in-game latency reducer for Radeon GPUs: it aligns CPU and GPU work so frames do not queue, cutting the time from input to screen. AMD pairs it with FSR Frame Generation.", ch: "9.3" },
    "archetype": { term: "Archetype", aka: ["chunk"], def: "In an entity component system, the group of entities that have exactly the same component types. They are stored together in fixed-size blocks of memory called chunks.", ch: "2.3" },
    "area-light": { term: "Area light", aka: ["rect light","Rect Light","AreaLight3D","disc light","tube light"], def: "A light that shines from a shape with real size, such as a rectangle or a disc. It gives soft shadows and broad highlights, and costs more than a point light.", ch: "7.1" },
    "art-director": { term: "Art director", aka: ["AD"], def: "The person who sets a game's visual direction and approves whether art, lighting and effects match it.", ch: "1.2" },
    "asset": { term: "Asset", aka: ["game asset","content"], def: "Any piece of content a game is built from, such as a model, texture, material, sound, animation or level, once the engine has imported it and can use it.", ch: "0.1" },
    "asset-cooking": { term: "Cooking", aka: ["cook","asset cooking","content build"], def: "Converting imported assets into the exact form one platform loads: textures compressed into that GPU's formats, shaders compiled, and anything the game never uses left out.", ch: "1.3" },
    "asset-database": { term: "Asset database", aka: ["asset registry","AssetDatabase","Asset Registry"], def: "The engine's record of every asset under a stable ID, with its type, location and dependencies, so references survive renames and moves.", ch: "1.3" },
    "asset-import": { term: "Import", aka: ["asset import","importer","reimport"], def: "The engine step that reads an exported file and converts it into the engine's own representation, using import settings stored alongside it.", ch: "1.3" },
    "asset-system": { term: "Asset system", aka: ["asset manager","resource manager","asset database"], def: "The engine system that finds, loads, tracks and unloads a game's content files, such as meshes, textures and sounds, so other systems can ask for them by name.", ch: "2.1" },
    "asset-validation": { term: "Asset validation", aka: ["data validation","asset checks","content validation"], def: "Automatic checks that every asset follows the project's rules, such as naming, triangle and texture-size budgets, and references only to files that exist.", ch: "1.3" },
    "astc": { term: "ASTC", aka: ["Adaptive Scalable Texture Compression","ASTC 4x4","ASTC 6x6","ASTC HDR"], def: "A texture format designed by Arm and AMD, used mainly on phones and Apple devices. Every block is 128 bits, but each texture picks a block size from 4 × 4 to 12 × 12 texels, from 8 down to 0.89 bits per pixel.", ch: "6.3" },
    "async-compute": { term: "Async compute", aka: ["asynchronous compute","AsyncCompute","compute queue","Asynchronous Execution"], def: "Running compute shader passes on a second GPU queue at the same time as drawing, so work that uses different parts of the GPU, such as AO beside a shadow pass, overlaps instead of waiting in line.", ch: "10.1" },
    "async-loading": { term: "Asynchronous loading", aka: ["async loading","background loading","RequestAsyncLoad","LoadAssetAsync","load_threaded_request"], def: "Reading and preparing assets on other threads while the game keeps running, leaving only small final steps for the game thread, so loading does not freeze a frame.", ch: "11.4" },
    "attenuation-radius": { term: "Attenuation radius", aka: ["range","Range","light radius","Attenuation Radius"], def: "The distance beyond which the renderer ignores a light, so it does not cost shading work across the whole world. Engines fade the light smoothly to zero there.", ch: "7.1" },
    "attribute-interpolation": { term: "Attribute interpolation", aka: ["interpolation","varying interpolation"], def: "Blending the values a vertex shader writes for a triangle's three corners, such as colour, UVs and normals, to get a value at each covered pixel.", ch: "5.3" },
    "audio-engine": { term: "Audio engine", aka: ["audio","sound system","audio middleware"], def: "The engine system that plays and mixes sounds, places them in 3D space relative to the listener, and streams music and dialogue.", ch: "2.1" },
    "auto-exposure": { term: "Auto-exposure", aka: ["eye adaptation","automatic exposure","adaptive exposure","Auto Exposure Histogram"], def: "Exposure set from the frame itself: the renderer measures the scene's brightness and moves exposure towards a target over time, like eyes adjusting after leaving a tunnel.", ch: "9.1" },
    "backface-culling": { term: "Backface culling", aka: ["face culling"], def: "Skipping triangles that face away from the camera. The GPU decides which way a triangle faces from the order of its corners on screen.", ch: "4.4" },
    "bake-cage": { term: "Cage", aka: ["bake cage","projection cage","envelope","max ray distance"], def: "An inflated copy of the low-poly mesh that baking rays start from, travelling inwards to find the high-poly surface. Its distance decides which part of the sculpt each texel records.", ch: "6.4" },
    "baked-lighting": { term: "Baked lighting", aka: ["precomputed lighting","light baking"], def: "Lighting calculated ahead of time, usually in the editor, and stored in textures or probes. Cheap at runtime and high quality, but it cannot react to things that move.", ch: "8.2" },
    "baking": { term: "Baking", aka: ["texture baking","mesh map baking","normal map baking"], def: "Transferring detail into a texture ahead of time, most often from a high-poly sculpt onto a low-poly mesh as normal and ambient occlusion maps.", ch: "1.3" },
    "bandwidth-bound": { term: "Bandwidth-bound", aka: ["memory-bound","memory bandwidth bound","VRAM-bound"], def: "A GPU pass limited by how many bytes it moves to and from memory, common for full-screen passes over large images. Smaller formats, fewer passes and lower resolutions make it faster; simpler maths does not.", ch: "11.2" },
    "barycentric-coordinates": { term: "Barycentric coordinates", aka: ["barycentrics","barycentric weights"], def: "Three weights, one per corner of a triangle, that say how close a point is to each corner. They add up to 1, and a weight below 0 means the point is outside the triangle.", ch: "5.3" },
    "batching": { term: "Batching", aka: ["draw call batching","batch"], def: "Any technique that turns many draw requests into fewer or cheaper ones, such as merging meshes, sorting draws by material or instancing.", ch: "4.3" },
    "bc1": { term: "BC1", aka: ["DXT1"], def: "A block-compressed format storing RGB, with optional on-or-off alpha, at 4 bits per pixel: two endpoint colours and a 2-bit index per texel. Used for opaque colour and packed masks.", ch: "6.3" },
    "bc3": { term: "BC3", aka: ["DXT5"], def: "A block-compressed format at 8 bits per pixel: RGB stored as in BC1, plus a separately compressed alpha channel. Used for colour textures with smooth transparency.", ch: "6.3" },
    "bc4": { term: "BC4", aka: ["ATI1","RGTC1","R Compressed BC4"], def: "A single-channel block-compressed format at 4 bits per pixel, with eight levels between two endpoints in each block. Used for roughness, height and other single masks.", ch: "6.3" },
    "bc5": { term: "BC5", aka: ["ATI2","3Dc","RGTC2","RG Compressed BC5"], def: "A two-channel block-compressed format at 8 bits per pixel, each channel stored like BC4. The standard format for normal maps, which keep X and Y and rebuild Z in the shader.", ch: "6.3" },
    "bc6h": { term: "BC6H", aka: ["BC6","HDR Compressed"], def: "A block-compressed format for high dynamic range RGB at 8 bits per pixel, storing 16-bit floating-point colour. Used for skies, light probes and lightmaps instead of 64-bit float textures.", ch: "6.3" },
    "bc7": { term: "BC7", aka: ["BPTC"], def: "A high-quality block-compressed format for RGB or RGBA at 8 bits per pixel. Each 4 × 4 block picks one of eight modes, some with up to three pairs of endpoint colours.", ch: "6.3" },
    "bcn": { term: "BCn", aka: ["BC formats","block compression formats","DXTn","BPTC","RGTC"], def: "The family of block-compressed texture formats numbered BC1 to BC7, used on PCs and consoles. Each stores 4 × 4 texel blocks in 8 or 16 bytes and suits a different kind of data.", ch: "6.3" },
    "bent-normal": { term: "Bent normal", aka: [], def: "The average direction of open sky seen from a point. Where a surface is partly enclosed it leans away from the occluders, and engines use it to light and reflect more convincingly.", ch: "8.3" },
    "beta": { term: "Beta", aka: [], def: "The milestone at which a game is feature and content complete, and the remaining work is fixing bugs, optimising and polishing before release.", ch: "1.1" },
    "bilateral-filter": { term: "Bilateral filter", aka: ["depth-aware blur","edge-aware blur"], def: "A blur that only mixes neighbouring pixels at a similar depth and facing. It smooths noise without smearing one object's values onto another.", ch: "8.3" },
    "bilinear-filtering": { term: "Bilinear filtering", aka: ["bilinear","linear filtering","Bi-linear"], def: "Blending the four texels around the sample point, each weighted by how close it is, so magnified textures look smooth instead of blocky.", ch: "6.2" },
    "billboard": { term: "Billboard", aka: ["camera-facing card","Billboard Renderer","Billboard Mode"], def: "A flat card that turns to face the camera every frame. Used for impostors, distant trees and many particles.", ch: "4.5" },
    "bind-pose": { term: "Bind pose", aka: ["rest pose","reference pose","T-pose","A-pose","inverse bind matrix"], def: "The pose a skinned mesh was modelled and weighted in. Skinning measures each vertex relative to its bones in this pose, then applies how far each bone has moved since.", ch: "4.6" },
    "binning": { term: "Binning", aka: ["binning pass","tiling pass","geometry phase","bins","tile lists"], def: "The first phase of a tile-based GPU's render pass: every triangle is positioned and added to a list for each screen tile it touches, and the lists go to memory for the tile-by-tile drawing that follows.", ch: "10.2" },
    "bit-depth": { term: "Bit depth", aka: ["8-bit","10-bit","bits per channel","bpc"], def: "How many bits store each colour channel. 8 bits give 256 levels per channel; 10 bits give 1,024, which HDR signals need to avoid visible steps.", ch: "3.2" },
    "bitangent": { term: "Bitangent", aka: ["binormal"], def: "The third direction of the tangent frame, along the texture's vertical axis and at right angles to the normal and tangent. It is usually rebuilt from the normal, the tangent and a stored sign rather than stored itself.", ch: "4.1" },
    "bits-per-pixel": { term: "Bits per pixel", aka: ["bpp","bits per texel","bpt","bit rate"], def: "How much memory a texture format uses per texel, on average: 32 for RGBA8, 8 for BC7, 4 for BC1. Multiply by width × height and divide by 8 to get bytes.", ch: "6.3" },
    "blas": { term: "BLAS", aka: ["bottom-level acceleration structure","bottom-level AS"], def: "The acceleration structure for one mesh's triangles, built in the mesh's own coordinate space. Many instances of the mesh share one BLAS.", ch: "8.6" },
    "blend-mode": { term: "Blend mode", aka: ["blend state","blending mode","blend equation"], def: "The rule the GPU uses to combine a new colour with the colour already in the image: replace it, mix by alpha, add, multiply and so on. Engines expose it as a material setting.", ch: "5.5" },
    "blend-shape": { term: "Blend shape", aka: ["morph target","shape key","blendshape"], def: "A stored version of a mesh in another shape, such as a smile, kept as offsets from the original. Weights from 0 to 1 mix any number of them onto the base mesh.", ch: "4.6" },
    "blinn-phong": { term: "Blinn-Phong", aka: ["Blinn-Phong specular","Blinn"], def: "Jim Blinn's 1977 version of Phong's model, which measures the half vector against the normal instead of the reflection against the view. It was the specular model of OpenGL's fixed-function pipeline and of many games before physically based shading.", ch: "7.2" },
    "block-compression": { term: "Block compression", aka: ["texture compression","GPU texture compression","DXT","S3TC"], def: "Storing a texture as small blocks of texels, usually 4 × 4, each in the same small number of bytes, so the GPU can find and decode any block directly while sampling. It cuts texture memory four to eight times for a small loss of quality.", ch: "6.3" },
    "bloom": { term: "Bloom", aka: ["glow","Glow","veil","glare"], def: "A glow around very bright light, made by blurring the brightest parts of the HDR image at several sizes and adding a little of the result back before the tone curve.", ch: "9.4" },
    "blueprint": { term: "Blueprint", aka: ["Blueprint class","Blueprint Visual Scripting","BP"], def: "Unreal Engine's visual scripting system. A Blueprint class bundles an Actor's components, settings and node-based logic into an asset that can be placed many times, like a prefab.", ch: "2.3" },
    "bokeh": { term: "Bokeh", aka: ["bokeh shape","aperture shape","Blade Count"], def: "The look of out-of-focus areas, especially small bright lights, which take the shape of the lens aperture: hexagons for six straight blades, circles for rounded ones.", ch: "9.4" },
    "bone": { term: "Bone", aka: ["joint"], def: "One node of a skeleton: a transform with a parent. Animation sets its rotation, and sometimes its position and scale, and the vertices weighted to it move with it.", ch: "4.6" },
    "bottleneck": { term: "Bottleneck", aka: ["limiter", "limiting factor"], def: "The one part of the work that sets how long a frame takes, such as the GPU or the game thread. Speeding up anything else leaves the frame time unchanged until the bottleneck itself gets faster.", ch: "11.1" },
    "bounce": { term: "Bounce", aka: ["light bounce","indirect bounce","bounces"], def: "One reflection of light off a surface on its way from a light to the eye. Each bounce carries only part of the light before it, because surfaces absorb some and some escapes.", ch: "8.1" },
    "bounding-volume": { term: "Bounding volume", aka: ["bounds","bounding box","AABB","axis-aligned bounding box","bounding sphere","OBB"], def: "A simple shape, usually a box aligned with the world axes (AABB) or a sphere, that fully encloses an object. Culling tests these shapes instead of the object's triangles.", ch: "4.4" },
    "box-projection": { term: "Box projection", aka: ["parallax-corrected cubemap","parallax correction","proxy volume","Box Projection"], def: "Correcting a reflection probe by first intersecting each reflected ray with a box matching the room, then reading the cubemap towards that hit point. Reflections of the walls stop sliding as the camera moves.", ch: "7.6" },
    "brdf": { term: "BRDF", aka: ["bidirectional reflectance distribution function","reflectance model"], def: "The function that says how much of the light arriving from one direction a surface sends towards another. Most engines use Lambert diffuse plus a GGX microfacet specular term.", ch: "6.5" },
    "budget-allocation": { term: "Budget allocation", aka: ["per-system budget","budget split","millisecond budget","performance budget"], def: "Dividing a frame budget into milliseconds for each system and pass, such as 2 ms for shadows or 3 ms for animation, so each team owns a number and every capture can be checked against it.", ch: "11.1" },
    "build": { term: "Build", aka: ["game build","packaged build","package"], def: "A runnable copy of the game for one platform: compiled code plus cooked assets, packed into a few large files.", ch: "1.3" },
    "bump-mapping": { term: "Bump mapping", aka: ["bump map"], def: "Tilting the shading normal per pixel using the slopes of a height map, so a surface looks bumpy without changing shape. Introduced by James Blinn in 1978; normal maps are its modern form.", ch: "6.4" },
    "bvh": { term: "BVH", aka: ["bounding volume hierarchy","BVH tree"], def: "A tree of boxes: each box encloses the boxes below it, and the smallest boxes hold a few triangles. A ray that misses a box skips everything inside it, so it tests tens of boxes instead of millions of triangles.", ch: "8.6" },
    "bvh-refit": { term: "Refit", aka: ["BVH refit","BVH update","acceleration structure update","PERFORM_UPDATE"], def: "Updating a BVH after vertices move by regrowing its boxes to fit, keeping the same tree. It is much faster than a rebuild, but the boxes grow loose and rays slow down if the mesh changes shape a lot.", ch: "8.6" },
    "candela": { term: "Candela", aka: ["cd","candelas","luminous intensity"], def: "The unit of how strong a light source is in one direction. A candle is about 1 candela, and a point light of 1 candela gives about 12.6 lumens in total.", ch: "7.1" },
    "candy-wrapper": { term: "Candy-wrapper artefact", aka: ["candy wrapper","joint collapse","volume loss"], def: "The collapse of a twisting joint under linear blend skinning, which pinches the mesh to a thin waist like the twisted ends of a sweet wrapper. Strong bends show a milder version.", ch: "4.6" },
    "capsule-shadows": { term: "Capsule shadows", aka: ["Capsule Direct Shadow","Capsule Indirect Shadow","Shadow Physics Asset"], def: "Soft character shadows in Unreal Engine cast from a set of capsules attached to the character's bones, mainly to ground characters in areas lit by baked or bounced light.", ch: "7.5" },
    "cascade-split": { term: "Cascade split", aka: ["split distance","Split 1","Distribution Exponent","split scheme"], def: "The distance from the camera where one shadow cascade ends and the next begins. Splits are placed evenly, logarithmically or by a blend of the two.", ch: "7.5" },
    "cascaded-shadow-maps": { term: "Cascaded shadow maps", aka: ["CSM","shadow cascades","cascades","PSSM","parallel-split shadow maps"], def: "Splitting the camera's view into a few distance ranges and giving each its own shadow map, so nearby ground gets small texels and distant ground large ones. Each cascade is another shadow pass.", ch: "7.5" },
    "caustics": { term: "Caustics", aka: ["water caustics","caustic pattern"], def: "The bright, moving network of light that a wavy water surface focuses onto the floor below it. Games usually project an animated or simulated pattern instead of tracing the light.", ch: "9.6" },
    "certification": { term: "Certification", aka: ["cert","submission","TRC","TCR","Xbox Requirements","XR","Lotcheck","VRC"], def: "The platform holder's testing of a submitted build against its published requirements before a game or update may be released. A failed build must be fixed and resubmitted.", ch: "1.4" },
    "channel-packing": { term: "Channel packing", aka: ["packed texture","ORM map","mask map"], def: "Storing up to four single-value maps, such as occlusion, roughness and metallic, in the red, green, blue and alpha channels of one texture. It must be imported as linear data, not sRGB.", ch: "6.1" },
    "chromatic-aberration": { term: "Chromatic aberration", aka: ["CA","colour fringing","color fringing"], def: "Red and blue fringes along high-contrast edges, growing towards the edges of the frame, imitating a lens that does not focus all colours at the same point.", ch: "9.4" },
    "circle-of-confusion": { term: "Circle of confusion", aka: ["CoC","blur circle","blur disc"], def: "The disc an out-of-focus point spreads into on the sensor. Its size follows from the lens's focal length, aperture and focus distance and the point's distance; depth of field blurs each pixel by it.", ch: "9.4" },
    "clip-space": { term: "Clip space", aka: ["homogeneous clip space","clip coordinates","HClip"], def: "The four numbers (x, y, z, w) a vertex shader outputs for each vertex after the projection matrix. The GPU uses them to cut away anything outside the view before dividing by w.", ch: "3.4" },
    "clipmap": { term: "Clipmap", aka: ["clipmap level","clipmap levels"], def: "A stack of textures centred on the camera, each covering twice the area of the one inside it at the same resolution, so detail falls off with distance. Unreal's virtual shadow maps use one for the sun.", ch: "7.5" },
    "cloth-shading": { term: "Cloth shading", aka: ["sheen","fabric shading","Cloth shading model"], def: "A shading model for fabrics such as velvet and wool that adds a soft sheen where loose fibres catch light at grazing angles, which the default model cannot produce.", ch: "7.2" },
    "cluster-lod": { term: "Cluster LOD", aka: ["cluster-based LOD","cluster hierarchy"], def: "Choosing level of detail per small cluster of triangles instead of per object, so near and far parts of one mesh get different detail. Nanite is the best-known example.", ch: "4.5" },
    "clustered-shading": { term: "Clustered shading", aka: ["clustered lighting","clustered forward","clustered deferred"], def: "Light culling that cuts the view into a 3D grid of clusters, screen tiles sliced in depth, and lists the lights reaching each cluster. Unlike tiles, it does not count lights floating in the empty space between near and far objects.", ch: "7.3" },
    "colour-banding": { term: "Colour banding", aka: ["banding","contouring","posterisation"], def: "Visible stripes or steps in what should be a smooth gradient, such as a sky or fog, because too few levels are available to store it.", ch: "3.2" },
    "colour-bleeding": { term: "Colour bleeding", aka: ["color bleeding","colour bleed"], def: "One surface's colour tinting its neighbours through bounced light, such as a red wall turning the floor beside it pink. Too strong usually means albedo or bounce settings are too high.", ch: "8.1" },
    "colour-channel": { term: "Colour channel", aka: ["channel","R, G, B, A","alpha channel"], def: "One of the separate numbers stored for each pixel, such as red, green, blue or alpha (opacity). Each channel is stored with a fixed number of bits.", ch: "3.2" },
    "colour-gamut": { term: "Colour gamut", aka: ["gamut","primaries","Rec. 2020","DCI-P3"], def: "The range of colours a colour space or display can produce, set by its red, green and blue primaries. Rec. 2020, used by HDR10, covers far more colours than sRGB.", ch: "3.2" },
    "colour-grading": { term: "Colour grading", aka: ["color grading","grading","colour correction","look"], def: "Adjusting the frame's colours for mood and consistency: contrast, saturation, tints for shadows and highlights, curves. Done on scene-referred values before the tone curve, or through a LUT after it.", ch: "9.1" },
    "colour-temperature": { term: "Colour temperature", aka: ["color temperature","Kelvin","Temperature","CCT"], def: "A light's tint described as the temperature, in kelvin, of a glowing object of that colour. A candle flame is about 1,850 K and orange; 6,500 K is neutral daylight white; higher values look blue.", ch: "7.1" },
    "command-buffer": { term: "Command buffer", aka: ["command list"], def: "A recorded list of GPU instructions, such as which settings to use, which buffers to read and what to draw. The CPU builds it, then hands it to the GPU in one go.", ch: "2.2" },
    "component": { term: "Component", aka: ["Actor Component","MonoBehaviour","fragment"], def: "A piece of data or behaviour attached to an object, such as a mesh, a collider, a light or a script. Objects are built by combining components.", ch: "2.3" },
    "compute-shader": { term: "Compute shader", aka: [], def: "A GPU program that is not tied to drawing triangles. Renderers use compute shaders for post effects, AO, culling and simulation.", ch: "5.6" },
    "compute-unit": { term: "Compute unit", aka: ["CU","SM","streaming multiprocessor","GPU core","shader core"], def: "The repeated building block of a GPU: a set of lanes with its own scheduler, registers, small cache and texture units. A GPU has anywhere from a handful to well over a hundred.", ch: "3.5" },
    "concept-phase": { term: "Concept phase", aka: ["concept","ideation"], def: "The first phase of a game project, where a few people define the idea, audience, platforms, scope and rough cost. It ends with a pitch and a decision on whether to fund pre-production.", ch: "1.1" },
    "constant-buffer": { term: "Constant buffer", aka: ["uniform buffer","cbuffer","UBO","uniforms"], def: "A small block of values the CPU sets for a draw, such as a material's tint or the camera's position, that stays the same for every vertex and pixel in that draw.", ch: "5.6" },
    "contact-shadows": { term: "Contact shadows", aka: ["screen-space shadows","Contact Shadow Length","screen space contact shadows"], def: "Small shadows found by stepping a short way from each pixel towards the light through the depth buffer. They restore shadows where objects touch surfaces and fine detail shadow maps are too coarse to hold.", ch: "7.5" },
    "content-complete": { term: "Content complete", aka: ["asset complete"], def: "The point at which every level, asset, line of dialogue and piece of interface is in the game in final or near-final form, so only fixes and polish remain.", ch: "1.1" },
    "content-pipeline": { term: "Content pipeline", aka: ["asset pipeline","art pipeline"], def: "The chain of tools, rules and people that carries art from the programs artists make it in, through the engine, into the files that ship with the game.", ch: "1.3" },
    "continuous-integration": { term: "Continuous integration", aka: ["CI","build server","build farm"], def: "Build machines that pick up every submitted change, build and test it automatically, and report failures to the team.", ch: "1.3" },
    "cook-torrance": { term: "Cook-Torrance", aka: ["Cook-Torrance microfacet model","microfacet specular"], def: "The microfacet specular model physically based renderers use: a facet distribution D (usually GGX), a Fresnel term F and a shadowing term G, combined as D × F × G ÷ (4 (N·L)(N·V)).", ch: "7.2" },
    "cooked-asset": { term: "Cooked asset", aka: ["cooked content","runtime asset"], def: "An asset converted for one platform: compressed, resized and stripped of editor-only data. It loads fast and is not meant to be edited.", ch: "1.3" },
    "coordinate-space": { term: "Coordinate space", aka: ["space","coordinate system","coordinate frame","frame of reference"], def: "An origin plus a set of axes that positions are measured from. The same corner of a model has different numbers in each space.", ch: "3.4" },
    "cpu": { term: "CPU", aka: ["central processing unit","processor"], def: "The general-purpose processor that runs game logic and the engine, and prepares the work the GPU will do each frame.", ch: "3.5" },
    "cpu-bound": { term: "CPU-bound", aka: ["CPU bound","CPU-limited","game-thread bound","render-thread bound"], def: "A frame whose time is set by a CPU thread, such as the game thread or the render thread, while the GPU waits. Lowering the resolution does not speed it up; less CPU work does.", ch: "11.1" },
    "cpu-cache": { term: "CPU cache", aka: ["cache line","cache miss"], def: "Small, fast memory beside each CPU core. Data arrives in blocks called cache lines, usually 64 bytes; needing data that is not there is a cache miss and can take around 200 times longer than a hit.", ch: "2.3" },
    "critical-path": { term: "Critical path", aka: ["longest dependency chain","serial path"], def: "The longest chain of work in a frame that has to happen in order because each step needs the one before. However many cores a job system uses, the frame cannot finish sooner than this chain.", ch: "11.3" },
    "cross-compilation": { term: "Shader cross-compilation", aka: ["cross-compiling","DXC","SPIRV-Cross","shader translation"], def: "Compiling one shader source into the different formats each graphics API needs, such as DXIL for Direct3D 12, SPIR-V for Vulkan and a Metal library, so a team writes each shader once.", ch: "5.6" },
    "cross-product": { term: "Cross product", aka: ["vector product","cross"], def: "An operation on two 3D vectors that gives a third vector at right angles to both, as long as the area of the parallelogram they span. Swapping the two inputs makes it point the opposite way.", ch: "3.3" },
    "crowd-rendering": { term: "Crowd rendering", aka: ["crowds","crowd system","animation instancing"], def: "Drawing hundreds or thousands of animated characters at once, usually with instancing, baked vertex animation, simple skeletons and aggressive level of detail.", ch: "4.6" },
    "crunch": { term: "Crunch", aka: ["crunch time","crunch mode"], def: "Sustained long working hours used to hit a deadline. It raises output briefly, then costs mistakes, health and experienced people leaving.", ch: "1.1" },
    "cubemap": { term: "Cubemap", aka: ["cube map","cube texture","TextureCube"], def: "Six square images forming the faces of a cube, read with a direction instead of UV coordinates. Skies and reflections use them.", ch: "6.1" },
    "culling": { term: "Culling", aka: ["visibility culling","visibility determination"], def: "Finding objects, or parts of them, that cannot affect the image and skipping them before they cost any drawing work. Frustum, occlusion, distance and backface culling are the main kinds.", ch: "4.4" },
    "custom-engine": { term: "Custom engine", aka: ["in-house engine","proprietary engine"], def: "An engine a studio builds and maintains for its own games, such as Guerrilla's Decima. It can fit the studio's needs exactly, but it needs a permanent team to keep it going.", ch: "2.4" },
    "day-one-patch": { term: "Day-one patch", aka: ["launch patch","day-zero patch"], def: "An update released on or before launch day that players download over the gold master. It carries fixes made after the release build was locked.", ch: "1.1" },
    "dcc-tool": { term: "DCC tool", aka: ["digital content creation tool","content creation software"], def: "A program artists make game content in, such as Blender, Maya, 3ds Max, Houdini, ZBrush or Substance 3D Painter. Each saves its own working file format.", ch: "1.3" },
    "ddgi": { term: "DDGI", aka: ["dynamic diffuse global illumination","RTXGI","irradiance probes with visibility"], def: "A grid of probes that trace rays every frame and store both the light they see and the distance to the nearest surface in each direction. The distances let a pixel ignore probes on the far side of a wall, which cuts light leaking.", ch: "8.5" },
    "deferred-decal": { term: "Deferred decal", aka: ["DBuffer decal","D-buffer decal","screen-space decal","decal projector"], def: "A decal drawn as a box that projects onto the surfaces already stored inside it, changing their base colour, normals or roughness before lighting, so it is lit exactly like the surface under it.", ch: "7.3" },
    "deferred-rendering": { term: "Deferred rendering", aka: ["deferred shading"], def: "A way of organising a frame that first writes each pixel's surface properties to a G-buffer and lights them in a later pass. It handles many lights well.", ch: "7.3" },
    "delta-time": { term: "Delta time", aka: ["dt","variable timestep","DeltaSeconds","Time.deltaTime"], def: "The time that passed since the previous frame. Update code multiplies speeds by it so that objects move the same distance per second at any frame rate.", ch: "2.2" },
    "denoising": { term: "Denoising", aka: ["denoiser"], def: "Turning a noisy, under-sampled image into a clean one by blending neighbouring pixels and previous frames. Most real-time AO, GI and ray tracing depends on it.", ch: "8.7" },
    "depth-buffer": { term: "Depth buffer", aka: ["z-buffer","depth texture"], def: "A screen-sized image storing, for every pixel, how far the nearest visible surface is from the camera. It is the renderer's only record of the scene's shape after geometry is drawn.", ch: "5.5" },
    "depth-of-field": { term: "Depth of field", aka: ["DOF","DoF","focus blur","Cinematic DOF"], def: "The range of distances that look sharp through a lens, and the effect that blurs everything nearer or farther, by an amount computed from each pixel's depth.", ch: "9.4" },
    "depth-prepass": { term: "Depth pre-pass", aka: ["depth prepass","Z-prepass","early Z pass","depth priming"], def: "Drawing the opaque scene once with depth only, then again with full shading where each fragment must match the stored depth, so every visible pixel is shaded exactly once.", ch: "5.4" },
    "depth-test": { term: "Depth test", aka: ["z-test","ZTest","depth comparison"], def: "The GPU's per-pixel check that keeps a new fragment only if it is nearer than the distance already stored in the depth buffer. It is what lets solid objects be drawn in any order.", ch: "5.5" },
    "depth-write": { term: "Depth write", aka: ["z-write","ZWrite","depth draw mode"], def: "Storing a fragment's depth in the depth buffer after it passes the depth test. Opaque surfaces write depth; blended transparent surfaces usually test depth without writing it.", ch: "5.5" },
    "derived-data-cache": { term: "Derived data cache", aka: ["DDC","shared DDC","cache server","Unity Accelerator"], def: "A cache of processed versions of assets, such as compressed textures and compiled shaders, so work done once on one machine can be reused by the whole team.", ch: "1.3" },
    "detail-normal-map": { term: "Detail normal map", aka: ["detail map","detail normal","micro normal map"], def: "A small, tiling normal map of fine grain blended over a material's main normal map, adding close-up detail for almost no memory.", ch: "6.4" },
    "devkit": { term: "Devkit", aka: ["development kit","dev kit"], def: "A development version of a console or device, supplied by the platform holder under contract, that studios use to build, run and debug their game.", ch: "1.4" },
    "diffuse": { term: "Diffuse reflection", aka: ["diffuse"], def: "Light that a surface scatters evenly in all directions, so it looks the same from any viewing angle. Matte paint is mostly diffuse.", ch: "7.2" },
    "diffuse-gi": { term: "Diffuse GI", aka: ["diffuse indirect lighting","indirect diffuse","diffuse global illumination"], def: "Bounced light scattered evenly by matte surfaces. It does not change as the camera moves and varies smoothly, so it can be baked into lightmaps or stored in probes.", ch: "8.1" },
    "direct-light": { term: "Direct light", aka: ["direct lighting"], def: "Light that travels straight from a light source to a surface without bouncing off anything else first.", ch: "8.1" },
    "directional-light": { term: "Directional light", aka: ["sun light","Directional Light","DirectionalLight3D"], def: "A light so far away that its rays arrive parallel and equally strong everywhere, used for the sun and the moon. It has a direction and a brightness but no position.", ch: "7.1" },
    "directstorage": { term: "DirectStorage", aka: ["Microsoft DirectStorage","DStorage"], def: "Microsoft's Windows API for fast loading from NVMe drives. Games submit many reads in batches instead of one at a time, and can have the data decompressed on the GPU.", ch: "11.4" },
    "directx-12": { term: "DirectX 12", aka: ["Direct3D 12","D3D12","DX12"], def: "Microsoft's explicit graphics API for Windows and Xbox. The engine manages GPU memory and synchronisation itself, in exchange for much lower CPU overhead than older APIs.", ch: "3.5" },
    "discrete-gpu": { term: "Discrete GPU", aka: ["dedicated GPU","graphics card","dGPU"], def: "A GPU on its own card with its own VRAM, connected to the CPU through a PCI Express slot. Its VRAM is very fast, but data has to cross a much slower link to get there.", ch: "3.5" },
    "disocclusion": { term: "Disocclusion", aka: [], def: "Pixels that become visible this frame after being hidden last frame. Temporal techniques have no history for them, so they often show noise or ghosting there.", ch: "9.2" },
    "displacement": { term: "Displacement", aka: ["displacement mapping","vertex displacement","height displacement"], def: "Moving each vertex along its normal by an amount read from a height texture, so the surface's real shape and silhouette change. It needs enough vertices to carry the detail.", ch: "5.2" },
    "displacement-mapping": { term: "Displacement mapping", aka: ["displacement","vertex displacement","true displacement"], def: "Moving a mesh's real vertices along their normals by a height map, so the shape and its outline change. It needs enough vertices, often created by tessellation.", ch: "6.4" },
    "display-referred": { term: "Display-referred", aka: ["display referred","output-referred"], def: "Describing values as what the screen should show, from black up to its white or peak brightness. Values after tone mapping are display-referred.", ch: "9.1" },
    "distance-culling": { term: "Distance culling", aka: ["cull distance","draw distance","max draw distance","visibility range","Cull Distance Volume"], def: "Skipping objects beyond a set distance from the camera, usually shorter for smaller objects, because they would cover only a few pixels.", ch: "4.4" },
    "distance-field-shadows": { term: "Distance-field shadows", aka: ["distance field soft shadows","DF shadows","ray traced distance field shadows"], def: "Shadows found by tracing a ray towards the light through the scene's signed distance fields. The closest the ray passes to anything gives a soft edge; they are used far beyond the cascades.", ch: "7.5" },
    "distance-fog": { term: "Distance fog", aka: ["depth fog","linear fog","exponential fog","Exponential Squared","Fog (Lighting window)"], def: "Fog that hides the scene by distance from the camera alone, the same in every direction and at every height. One formula per pixel; the oldest and cheapest fog in games.", ch: "9.5" },
    "dithering": { term: "Dithering", aka: ["dither","debanding"], def: "Adding a tiny amount of noise before reducing an image to fewer levels, so hard steps become fine grain that the eye averages into a smooth gradient.", ch: "3.2" },
    "dlss": { term: "DLSS", aka: ["Deep Learning Super Sampling","DLSS Super Resolution","DLAA","DLSS 4","DLSS 4.5"], def: "NVIDIA's family of machine-learned rendering features for GeForce RTX GPUs: a temporal upscaler (Super Resolution, or DLAA at native resolution), frame generation and ray reconstruction.", ch: "9.3" },
    "dot-product": { term: "Dot product", aka: ["scalar product","dot"], def: "Multiply two vectors' matching components and add the results. For unit vectors the answer is the cosine of the angle between them: 1 when they point the same way, 0 at right angles and -1 when they point opposite ways.", ch: "3.3" },
    "dots": { term: "DOTS", aka: ["Unity Entities","Data-Oriented Technology Stack"], def: "Unity's data-oriented toolset, built around the Entities package, its entity component system. GameObjects are converted into entities in the editor, a step Unity calls baking.", ch: "2.3" },
    "double-buffering": { term: "Double buffering", aka: ["front buffer","back buffer"], def: "Using two framebuffers: the display reads the front one while the GPU draws into the back one, then the two swap roles.", ch: "3.1" },
    "draw-call": { term: "Draw call", aka: ["draw","DrawIndexed"], def: "One instruction from the CPU telling the GPU to draw a set of triangles with a given mesh, material and settings. Each one has a CPU cost, so engines try to need fewer.", ch: "4.3" },
    "draw-call-budget": { term: "Draw call budget", aka: ["draw call limit","draw call target"], def: "The number of draw calls per frame a project allows on each platform, set from how many the platform's CPU can record within the frame time alongside everything else.", ch: "4.3" },
    "driver": { term: "Graphics driver", aka: ["driver","GPU driver","display driver"], def: "Software from the GPU maker that turns graphics API commands into instructions for one particular GPU and compiles shaders into its machine code.", ch: "3.5" },
    "dual-quaternion-skinning": { term: "Dual-quaternion skinning", aka: ["DQS","dual quaternion blending","Preserve Volume"], def: "A skinning method that blends the bones' rotations and then rotates the vertex, so twisted and bent joints keep their thickness. It handles only rotation and movement, so scaled bones need extra work.", ch: "4.6" },
    "dxr": { term: "DXR", aka: ["DirectX Raytracing","DXR 1.1","DXR 1.2"], def: "Microsoft's ray tracing API for DirectX 12, announced in 2018: two-level acceleration structures, ray tracing shaders and, from tier 1.1, inline ray queries.", ch: "8.6" },
    "dynamic-batching": { term: "Dynamic batching", aka: [], def: "Combining small moving meshes on the CPU every frame by transforming their vertices into one shared buffer and drawing it once. The transform work grows with vertex count, so it only pays off for tiny meshes.", ch: "4.3" },
    "dynamic-buffer": { term: "Dynamic buffer", aka: ["dynamic vertex buffer","streaming buffer"], def: "A GPU buffer the CPU rewrites often, sometimes every frame. Used for particles, UI and procedurally generated geometry.", ch: "4.2" },
    "dynamic-light": { term: "Dynamic light", aka: ["movable light","real-time light","Movable","Realtime"], def: "A light computed every frame, so it can move, change and cast shadows from moving objects. Each one adds GPU time to every frame it is in view.", ch: "7.1" },
    "dynamic-resolution": { term: "Dynamic resolution", aka: ["dynamic resolution scaling","DRS","dynamic res","Allow Dynamic Resolution","r.DynamicRes"], def: "Lowering and raising the internal resolution every few frames, from measured GPU time, to stay within the frame budget. An upscaler then brings each frame to the display resolution.", ch: "9.3" },
    "early-z": { term: "Early-Z", aka: ["early depth test","early depth testing","early-Z rejection","Hi-Z"], def: "A depth test the GPU runs before the pixel shader, so fragments already hidden behind something drawn earlier are thrown away without being shaded.", ch: "5.4" },
    "ecs": { term: "Entity component system", aka: ["ECS","data-oriented design"], def: "A way to organise a game world as plain data: entities are ID numbers, components are data in tightly packed arrays, and systems are code that processes every entity with a given set of components.", ch: "2.3" },
    "ecs-system": { term: "System", aka: ["ECS system","processor"], def: "In an entity component system, code that runs over every entity with a particular set of components, for example moving everything that has a position and a velocity.", ch: "2.3" },
    "edge-aliasing": { term: "Edge aliasing", aka: ["jaggies","stair-stepping","geometric aliasing"], def: "Stair-step edges, broken-up thin objects and crawling pixels caused by testing coverage at only one point per pixel. Anti-aliasing techniques exist to reduce it.", ch: "5.3" },
    "editor": { term: "Editor", aka: ["level editor","authoring tools","Unreal Editor","Unity Editor"], def: "The engine's application for making a game: placing objects, importing content, tuning materials and testing. It stays on the team's machines and is not shipped to players.", ch: "2.1" },
    "emissive": { term: "Emissive surface", aka: ["emission","emissive material","Emissive Color","self-illumination"], def: "A surface whose material gives off its own light, such as a screen or a neon sign. It always glows, but lights other surfaces only through global illumination.", ch: "7.1" },
    "energy-conservation": { term: "Energy conservation", aka: ["energy conserving"], def: "The rule that a surface cannot send out more light than reaches it. PBR keeps it by dimming highlights as they spread and by not counting reflected light again as diffuse light.", ch: "6.5" },
    "engine-programmer": { term: "Engine programmer", aka: ["engine engineer","core programmer"], def: "A programmer who works on the engine's foundations, such as memory, threads, file loading, streaming and platform support, which every other system relies on.", ch: "1.2" },
    "entity": { term: "Entity", aka: [], def: "In an entity component system, an ID number that ties a set of components together. It has no data or behaviour of its own.", ch: "2.3" },
    "environment-map": { term: "Environment map", aka: ["env map","reflection map","environment cubemap","HDRI"], def: "A picture of the light arriving at one point from every direction, usually stored as a cubemap and read by direction. Exact for distant things such as the sky, increasingly wrong for nearby ones.", ch: "7.6" },
    "etc2": { term: "ETC2", aka: ["EAC","ETC2 RGB","ETC2 RGBA","ETC"], def: "A block-compressed texture format supported by every OpenGL ES 3.0 and Vulkan phone: 4 bits per pixel for RGB and 8 for RGBA. Its EAC variants store one or two channels.", ch: "6.3" },
    "exposure": { term: "Exposure", aka: ["Exposure Compensation","camera exposure","Post Exposure"], def: "The multiplier applied to scene light before the tone curve. It decides which brightness lands in the middle of the picture, as a camera's shutter, aperture and ISO do.", ch: "9.1" },
    "exposure-value": { term: "Exposure value", aka: ["EV","EV100","stop","stops"], def: "A log scale for exposure on which each step doubles or halves the light. EV100 is measured as for ISO 100 film; Unity's guide puts sunlit scenes around EV 14 and moonlit ones around EV 1.", ch: "9.1" },
    "extinction": { term: "Extinction", aka: ["out-scattering","absorption","Beer-Lambert law","Beer's law","transmittance"], def: "The light lost along a path through participating media, absorbed or scattered out of the path. The share that survives falls exponentially with distance and density, which is the Beer-Lambert law.", ch: "9.5" },
    "f0": { term: "F0", aka: ["reflectance at normal incidence","specular colour","base reflectivity"], def: "How much light a surface reflects when seen straight on. About 4% for most non-metals; for metals it is the base colour, from about 56% for iron to over 90% for silver.", ch: "6.5" },
    "far-plane": { term: "Far plane", aka: ["far clip plane","far clipping plane","zfar","draw distance"], def: "The distance beyond which the camera draws nothing. Some renderers place it at infinity.", ch: "3.4" },
    "fbx": { term: "FBX", aka: [".fbx"], def: "Autodesk's 3D exchange format for meshes, materials, skeletons, animation, cameras and lights. The file format is undocumented, so programs read and write it through Autodesk's SDK.", ch: "1.3" },
    "feature-stack": { term: "Feature stack", aka: ["rendering feature stack","UE5 feature set","Nanite, Lumen, VSM, TSR"], def: "The set of large rendering systems a game or engine is built around, such as Nanite, Lumen, virtual shadow maps and TSR in Unreal Engine 5. The parts are designed to work together, so turning one off often changes what the others cost.", ch: "10.3" },
    "file-locking": { term: "File locking", aka: ["exclusive checkout","lock","Smart Locks","checkout"], def: "Letting only one person change a file at a time. Used for binary files such as models and textures, where two people's edits cannot be merged.", ch: "1.3" },
    "fill-rate": { term: "Fill rate", aka: ["pixel fill rate","fill-rate-bound","fill-bound","ROP-bound","pixel rate"], def: "How many pixels per second a GPU's output stage can depth-test, blend and write. A pass whose cost follows the number of pixels and layers drawn is often called fill-rate-bound.", ch: "11.2" },
    "fill-rule": { term: "Fill rule", aka: ["top-left rule","rasterization rules"], def: "The rule that decides which triangle owns a pixel whose centre lies exactly on an edge two triangles share. Direct3D and OpenGL use the top-left rule, so every pixel along the edge is drawn exactly once.", ch: "5.3" },
    "film-grain": { term: "Film grain", aka: ["grain","Grain","film noise"], def: "Fine noise added fresh every frame to imitate photographic film. It also breaks up colour banding.", ch: "9.4" },
    "filmic-tone-mapping": { term: "Filmic tone mapping", aka: ["filmic","filmic tonemapper","Filmic"], def: "Tone curves shaped like photographic film's response, with a soft toe and a long shoulder, so bright areas keep detail and the middle keeps contrast.", ch: "9.1" },
    "fireflies": { term: "Fireflies", aka: ["firefly","hot pixels","Max Path Intensity","Maximum Intensity"], def: "Isolated, very bright pixels from rare paths that find a small, intense light, often by way of a mirror or glossy surface. They need huge sample counts to average away, so renderers often clamp them.", ch: "8.7" },
    "fixed-function-stage": { term: "Fixed-function stage", aka: ["fixed function","fixed-function hardware"], def: "A pipeline stage built into the GPU as dedicated circuitry, such as the rasterizer or the depth test. It cannot be programmed, only configured with settings such as the cull mode or the blend mode.", ch: "5.1" },
    "fixed-hardware": { term: "Fixed hardware", aka: ["fixed platform","closed hardware"], def: "A platform where every player has the same machine, such as one console model, so a game can be tuned and tested for exactly that hardware.", ch: "1.4" },
    "fixed-timestep": { term: "Fixed timestep", aka: ["fixed update","physics tick","FixedUpdate()","_physics_process()"], def: "Advancing a simulation, usually physics, in steps of a constant length such as 1/60 of a second, whatever the frame rate. Each rendered frame runs zero, one or several steps to keep up with real time.", ch: "2.2" },
    "flame-chart": { term: "Flame chart", aka: ["timeline view","call timeline","icicle chart","Timing Insights"], def: "A thread's function calls drawn along a time axis, each call as a bar under the call that made it, so a bar's width is how long that call took. Profilers use it to show where a frame's CPU time went.", ch: "11.3" },
    "flipbook": { term: "Flipbook", aka: ["flipbook animation","sprite sheet animation","SubUV","Sub UV Animation","Texture Sheet Animation"], def: "An animation stored as a grid of frames in one texture. A particle shows one cell at a time and steps through them as it ages, so smoke can billow without any geometry moving.", ch: "9.6" },
    "flow-map": { term: "Flow map", aka: ["flowmap","flow texture"], def: "A texture whose colours store a direction and speed for each point, used to push a material's texture coordinates so water, lava or clouds appear to stream around rocks and along channels.", ch: "9.6" },
    "forward-plus": { term: "Forward+", aka: ["Forward Plus","tiled forward rendering"], def: "Forward rendering with per-tile or per-cluster light lists, built after a depth pre-pass, so each pixel loops only over nearby lights. It keeps MSAA and easy transparency while handling many lights.", ch: "7.3" },
    "forward-rendering": { term: "Forward rendering", aka: ["forward shading"], def: "A way of organising a frame where each object is lit as it is drawn. Simple and good for transparency and mobile GPUs.", ch: "7.3" },
    "fov": { term: "Field of view", aka: ["FOV","view angle"], def: "How wide the camera sees, as an angle across either the height or the width of the screen. Engines differ on which of the two the number means.", ch: "3.4" },
    "fps": { term: "Frames per second", aka: ["fps","frame rate","framerate"], def: "How many finished images a game shows each second. At 60 fps a new image appears about every 16.7 milliseconds.", ch: "0.2" },
    "fragment": { term: "Fragment", aka: ["pixel candidate"], def: "One triangle's contribution to one pixel: the covered sample with its interpolated values, before the depth test and blending decide whether it becomes the pixel's colour.", ch: "5.4" },
    "frame": { term: "Frame", aka: [], def: "One complete image drawn by the game. At 60 frames per second each frame has about 16.7 milliseconds.", ch: "0.2" },
    "frame-budget": { term: "Frame budget", aka: ["budget"], def: "The time available to produce one frame at the target frame rate, split between systems: 16.7 ms at 60 fps, 11.1 ms at 90 fps, 33.3 ms at 30 fps.", ch: "11.1" },
    "frame-generation": { term: "Frame generation", aka: ["frame gen","FG","DLSS Frame Generation","Multi Frame Generation","MFG","FSR Frame Generation","XeSS Frame Generation","frame interpolation"], def: "Creating extra frames between rendered ones from the two frames around them, their motion vectors and depth, to raise the displayed frame rate. It smooths motion and adds latency.", ch: "9.3" },
    "frame-graph": { term: "Frame graph", aka: ["render graph","RDG","Render Dependency Graph"], def: "A description of a frame's passes and the render targets each reads and writes, from which the engine works out the order, skips unused passes, inserts synchronisation and reuses memory.", ch: "5.6" },
    "frame-latency": { term: "Frame latency", aka: ["input latency","input lag","input-to-photon latency","click-to-photon latency"], def: "The time from a player's input to the first image on screen that shows its effect. Every stage a frame passes through, and every frame it waits in a queue, adds to it.", ch: "2.2" },
    "frame-pacing": { term: "Frame pacing", aka: ["frame time consistency","judder","microstutter","Swappy"], def: "How evenly frames reach the screen. Two runs with the same average frame rate can feel very different if one shows its frames at uneven intervals, because objects jump uneven distances from one image to the next.", ch: "11.1" },
    "frame-time": { term: "Frame time", aka: ["frametime","milliseconds per frame","delta time"], def: "How long one frame takes, in milliseconds: 1000 divided by the frame rate. Unlike frame rates, the times of separate pieces of work add up, so budgets are set in milliseconds.", ch: "0.2" },
    "frame-time-graph": { term: "Frame-time graph", aka: ["frametime graph","frame time plot","stat UnitGraph"], def: "A chart of how long each frame took, one bar or point per frame in order, with the budget drawn as a line. It shows the hitches and uneven pacing that an fps counter averages away.", ch: "11.1" },
    "frame-timeline": { term: "Frame timeline", aka: ["GPU timeline","timing view","frame breakdown"], def: "A frame's passes drawn as bars along time, to scale, showing where the milliseconds go, what runs at the same time and how much of the budget is left.", ch: "10.1" },
    "framebuffer": { term: "Framebuffer", aka: ["frame buffer","colour buffer","render target"], def: "A block of GPU memory holding one whole image, one colour value per pixel. The display reads its picture from one framebuffer while the GPU draws the next frame into another.", ch: "3.1" },
    "framebuffer-fetch": { term: "Framebuffer fetch", aka: ["programmable blending","pixel local storage","PLS","subpassLoad","dynamic rendering local read","SetInputAttachment"], def: "A pixel shader reading the colour or depth already stored at its own pixel in the render target, without a separate pass. On tile-based GPUs it lets deferred lighting read the G-buffer straight from tile memory.", ch: "10.2" },
    "fresnel": { term: "Fresnel effect", aka: ["Fresnel","Schlick's approximation","Schlick Fresnel"], def: "The rise in reflection as a surface is seen closer to edge-on. Water reflects about 2% of light looking straight down and nearly all of it at grazing angles.", ch: "6.5" },
    "froxel": { term: "Froxel", aka: ["frustum voxel","froxels","froxel grid","froxel buffer","volumetric fog grid"], def: "One cell of a 3D grid aligned with the camera's view: a screen tile in width and height and a depth slice deep, with slices getting deeper further from the camera. Volumetric fog and aerial perspective store their values in froxels.", ch: "9.5" },
    "frustum": { term: "View frustum", aka: ["frustum","camera frustum"], def: "The shape of the space a camera can see: a pyramid with its tip cut off, bounded by the near plane, the far plane and four sides set by the field of view.", ch: "3.4" },
    "frustum-culling": { term: "Frustum culling", aka: ["view frustum culling","view culling"], def: "Skipping objects whose bounding volume lies entirely outside the camera's view frustum. It is cheap and every engine does it automatically.", ch: "4.4" },
    "fsr": { term: "FSR", aka: ["AMD FidelityFX Super Resolution","FSR Upscaling","FSR 4","FSR 3.1","FSR 2","FSR Redstone"], def: "AMD's upscaling family: FSR 1 is spatial, FSR 2 and 3 are hand-written temporal upscalers for most GPUs, and FSR Upscaling 4 is machine-learned for recent Radeon GPUs. FSR Frame Generation adds frames.", ch: "9.3" },
    "fxaa": { term: "FXAA", aka: ["Fast Approximate Anti-Aliasing"], def: "Timothy Lottes's post-process anti-aliasing from NVIDIA: one full-screen pass over the tone-mapped image that finds high-contrast edges and blends along them. Very cheap and slightly soft.", ch: "9.2" },
    "g-buffer": { term: "G-buffer", aka: ["geometry buffer"], def: "A set of screen-sized images holding each pixel's surface data, such as colour, normal, roughness and depth, written before lighting in deferred rendering.", ch: "7.3" },
    "g-buffer-layout": { term: "G-buffer layout", aka: ["G-buffer format","G-buffer packing"], def: "Which values a deferred renderer stores in its G-buffer, in which render targets and formats, and so how many bytes each pixel costs. Optimised layouts typically use 16 to 32 bytes per pixel.", ch: "7.3" },
    "game-engine": { term: "Game engine", aka: ["engine"], def: "The reusable software a game is built on: runtime systems such as rendering, physics, animation and audio that run every frame, plus the editor and tools used to make the game's content.", ch: "2.1" },
    "game-loop": { term: "Game loop", aka: ["main loop","frame loop"], def: "The loop at the heart of every game that, once per frame, reads input, updates the game world, draws the new image and hands it to the display.", ch: "0.2" },
    "game-thread": { term: "Game thread", aka: ["main thread","GameThread"], def: "The CPU thread that runs the game loop: it reads input, runs gameplay code and updates the world. Most engines also call it the main thread.", ch: "2.2" },
    "gameobject": { term: "GameObject", aka: ["game object"], def: "Unity's object: a container for components that always has a Transform. Everything placed in a Unity scene is a GameObject.", ch: "2.3" },
    "gamma": { term: "Gamma", aka: ["gamma encoding","gamma correction","gamma space","transfer function"], def: "The curve that relates stored numbers to light output, close to light = value to the power 2.2. Values in gamma space look evenly spaced to the eye but give wrong results in lighting maths.", ch: "3.2" },
    "garbage-collection": { term: "Garbage collection", aka: ["GC","garbage collector","managed memory","GC.Collect"], def: "Reclaiming memory automatically: the runtime finds objects nothing refers to any more and frees them. Unity's C# scripts and Unreal's UObjects use it; the work can pause the thread that runs it.", ch: "11.3" },
    "gc-spike": { term: "GC spike", aka: ["garbage collection spike","GC pause","GC hitch","stop-the-world pause"], def: "A long frame caused by the garbage collector stopping a thread to do its work at once. It returns every few seconds in a game that allocates memory every frame.", ch: "11.3" },
    "generated-frame": { term: "Generated frame", aka: ["interpolated frame","intermediate frame","fake frame"], def: "A frame made by frame generation instead of the renderer. No input is read for it, and it can only be shown once the next rendered frame exists.", ch: "9.3" },
    "geometry-bound": { term: "Geometry-bound", aka: ["vertex-bound","triangle-bound","primitive-bound"], def: "A GPU pass limited by vertex shading, triangle setup or the rasteriser, such as a shadow pass over a dense scene. Lowering the resolution barely helps; fewer or larger triangles do.", ch: "11.2" },
    "ggx": { term: "GGX", aka: ["Trowbridge-Reitz","GGX distribution","normal distribution function","NDF"], def: "The formula almost every real-time renderer uses for how a surface's microfacets are tilted at a given roughness. Its long, soft tail around the highlight matches measured materials well.", ch: "6.5" },
    "ghosting": { term: "Ghosting", aka: ["smearing","trails"], def: "Faint trails behind moving objects, left when a temporal technique blends in history from a place the object has already left.", ch: "9.2" },
    "git-lfs": { term: "Git LFS", aka: ["Git Large File Storage","LFS"], def: "An extension to Git that keeps large files on a separate server and only small pointer files in the repository. It can also lock files that cannot be merged.", ch: "1.3" },
    "global-illumination": { term: "Global illumination", aka: ["GI","indirect lighting"], def: "Lighting that includes light bouncing between surfaces, not only light arriving straight from sources.", ch: "8.1" },
    "glsl": { term: "GLSL", aka: ["OpenGL Shading Language","GLSL ES"], def: "The Khronos Group's C-like shader language for OpenGL, OpenGL ES and WebGL, also usable for Vulkan through SPIR-V. Godot's shading language is closely based on it.", ch: "5.6" },
    "gltf": { term: "glTF", aka: ["glTF 2.0","GL Transmission Format",".gltf",".glb"], def: "An open 3D delivery format from the Khronos Group, standardised as ISO/IEC 12113:2022. It stores meshes, PBR materials, skins and animation, with fixed units (metres) and Y as up.", ch: "1.3" },
    "godot": { term: "Godot", aka: ["Godot Engine","Godot 4","GDScript"], def: "A free, open-source engine under the MIT licence, scripted mainly in its own language, GDScript, with three renderers: Forward+, Mobile and Compatibility.", ch: "2.4" },
    "godot-node": { term: "Node", aka: ["Node3D","Node2D","Godot node"], def: "Godot's building block. Each node does one job, such as drawing a mesh or casting light, and a small tree of nodes makes an object.", ch: "2.3" },
    "gold-master": { term: "Gold master", aka: ["gold","going gold","release build"], def: "The final release build, approved by the platform holders and locked, that is used to manufacture discs and seed digital stores.", ch: "1.1" },
    "gpu": { term: "GPU", aka: ["graphics processing unit","graphics card"], def: "The graphics processor: thousands of simple cores running the same small program on many vertices or pixels at once.", ch: "3.5" },
    "gpu-bound": { term: "GPU-bound", aka: ["GPU bound","GPU-limited"], def: "A frame whose time is set by the GPU while the CPU threads wait for it. Less GPU work, such as a lower resolution or cheaper effects, speeds it up; trimming game code does not.", ch: "11.1" },
    "gpu-counters": { term: "GPU counters", aka: ["hardware counters","performance counters","GPU metrics","perf counters"], def: "Measurements the GPU keeps for each of its units during a frame, such as how busy the shader cores, caches and memory were. Vendor and console tools read them to show why a pass is slow.", ch: "11.2" },
    "gpu-culling": { term: "GPU culling", aka: ["GPU occlusion culling","compute culling","GPU-driven culling"], def: "Culling done by compute shaders on the GPU, testing every instance or cluster against the frustum and a depth pyramid and writing the survivors for indirect draws, without a round trip to the CPU.", ch: "4.4" },
    "gpu-decompression": { term: "GPU decompression", aka: ["GDeflate","Zstandard GPU decompression","hardware decompression"], def: "Unpacking compressed game data with compute shaders on the graphics card, as DirectStorage can do with GDeflate, so the CPU does not have to. Consoles have dedicated decompression hardware for the same job.", ch: "11.4" },
    "gpu-driven-rendering": { term: "GPU-driven rendering", aka: ["GPU-driven pipeline","GPU Resident Drawer","GPU Scene"], def: "A way of rendering where the scene's object data lives on the GPU, compute shaders cull it and write the draw lists, and indirect draws consume them. The CPU's work stops growing with the number of objects.", ch: "4.3" },
    "gpu-occupancy": { term: "GPU occupancy", aka: ["occupancy","wave occupancy","warp occupancy","waves in flight"], def: "How many warps a compute unit has loaded compared with the most it could hold. Low occupancy leaves fewer warps to switch to while others wait for memory, so the shader cores sit idle.", ch: "11.2" },
    "gpu-particles": { term: "GPU particles", aka: ["GPU simulation","GPUComputeSim","GPU Compute Sim","VFX Graph","GPUParticles3D"], def: "Particles spawned and moved by compute shaders on the GPU instead of by the CPU. They allow hundreds of thousands to millions of particles, but game code cannot easily read them and the engine must be told their bounds.", ch: "9.6" },
    "gpu-queue": { term: "GPU queue", aka: ["command queue","render queue","frames in flight","submission"], def: "The line of submitted command buffers waiting for the GPU. The CPU submits a frame's work and moves on; the GPU runs it in order when it gets to it.", ch: "2.2" },
    "gpu-skinning": { term: "GPU skinning", aka: ["vertex shader skinning","compute skinning","skin cache"], def: "Bending an animated character's mesh on the GPU: each vertex is moved by a weighted blend of its bones' transforms, either in the vertex shader every time the mesh is drawn or once per frame in a compute shader whose result every pass reuses.", ch: "5.2" },
    "graphics-api": { term: "Graphics API", aka: ["API","rendering API"], def: "The published set of commands a program uses to drive a GPU, such as DirectX 12, Vulkan, Metal or WebGPU. Engines reach the GPU only through one.", ch: "3.5" },
    "graphics-mode": { term: "Graphics mode", aka: ["Performance mode","Quality mode","Fidelity mode","Resolution mode","120 FPS mode"], def: "A console game's menu choice between preset trade-offs, such as a Performance mode at 60 fps with a lower internal resolution and a Quality mode at 30 fps with more features. Each mode is its own frame budget.", ch: "10.3" },
    "graphics-pipeline": { term: "Graphics pipeline", aka: ["GPU pipeline","rendering pipeline","pipeline"], def: "The fixed sequence of stages a GPU puts every draw through: fetch the vertices, run the vertex shader, assemble triangles, find the pixels they cover, run the pixel shader, then test and blend the results into the image.", ch: "5.1" },
    "graphics-programmer": { term: "Graphics programmer", aka: ["rendering programmer","rendering engineer"], def: "A programmer who builds and optimises the renderer: lighting, shadows, the material system, post-processing and the code that drives the GPU. Graphics programmers also measure what each of those costs.", ch: "1.2" },
    "green-channel": { term: "Green channel convention", aka: ["OpenGL normal map","DirectX normal map","Y+","Y-","Flip Green Channel","Normal Map Invert Y"], def: "Which way green points in a normal map: up the texture in the OpenGL or Y+ convention, down in the DirectX or Y− convention. A map read with the wrong one makes bumps look like dents under vertical light.", ch: "6.4" },
    "gtao": { term: "GTAO", aka: ["ground-truth ambient occlusion","XeGTAO"], def: "A screen-space AO method that finds the two horizons in a few slices around each pixel and integrates the visible sky between them exactly, so it closely matches ray-traced AO for what the depth buffer shows.", ch: "8.3" },
    "hair-cards": { term: "Hair cards", aka: ["hair strips","card-based hair"], def: "Hair drawn as textured strips, each carrying an image of many hairs with alpha. Cheap and supported everywhere, but the strips must be sorted or dithered and look flat up close.", ch: "9.6" },
    "hair-strands": { term: "Hair strands", aka: ["strand-based hair","groom","Groom","strands"], def: "Hair drawn as tens of thousands of individual thin curves, each with its own shading and motion. Accurate up close but heavy, so engines limit it to high-end platforms and switch to cards at a distance.", ch: "9.6" },
    "half-vector": { term: "Half vector", aka: ["halfway vector","H"], def: "The unit vector half-way between the direction to the light and the direction to the camera, normalize(L + V). Where a surface's normal lines up with it, the surface mirrors the light into the camera.", ch: "7.2" },
    "halton-sequence": { term: "Halton sequence", aka: ["Halton (2, 3)","Halton[2,3]","low-discrepancy sequence"], def: "A sequence of points that fills a square evenly, each new point landing in the biggest gap left by the earlier ones. Temporal anti-aliasing and upscalers use its first 8 to 72 points as jitter offsets.", ch: "9.2" },
    "handedness": { term: "Handedness", aka: ["left-handed","right-handed","chirality"], def: "Whether a coordinate system's x, y and z axes match the thumb, index and middle finger of a left hand or a right hand. With x to the right and y up, z points into the screen in a left-handed system and out of it in a right-handed one.", ch: "3.4" },
    "hard-soft-edges": { term: "Hard and soft edges", aka: ["smoothing groups","sharp edges","smoothing angle","auto smooth"], def: "A per-edge shading choice. Across a soft edge the normals are shared and shading blends smoothly; across a hard edge each side keeps its own normal and the edge shows as a crease.", ch: "4.1" },
    "hbao": { term: "HBAO", aka: ["horizon-based ambient occlusion","HBAO+"], def: "A screen-space AO method that marches outward from each pixel in a few directions and records how high the surrounding surfaces rise above it.", ch: "8.3" },
    "hdr-display": { term: "HDR display", aka: ["HDR output","display HDR","HDR screen"], def: "A screen and signal that can show far brighter highlights and deeper colours than a standard (SDR) screen. The game must send a different signal to use it.", ch: "3.2" },
    "hdr-rendering": { term: "HDR rendering", aka: ["scene-referred rendering","high dynamic range rendering","floating-point render target"], def: "Lighting a frame with floating-point values that can rise far above 1.0, as real light does, and converting to the display's range only at the end. It is separate from HDR output.", ch: "3.2" },
    "hdr10": { term: "HDR10", aka: ["PQ","SMPTE ST 2084","perceptual quantizer"], def: "The most common HDR signal: 10-bit values on the PQ curve (SMPTE ST 2084), which encodes absolute brightness up to 10,000 nits, with Rec. 2020 primaries and fixed metadata.", ch: "3.2" },
    "hdrp": { term: "HDRP", aka: ["High Definition Render Pipeline"], def: "Unity's render pipeline for high-fidelity rendering on desktop, Xbox and PlayStation, with physical light units and advanced materials. From 2026 it receives maintenance and no new features.", ch: "2.4" },
    "headroom": { term: "Headroom", aka: ["frame headroom","budget headroom","safety margin","spare time"], def: "The part of the frame budget left unused on purpose in typical scenes, often about 10%, so spikes such as explosions, streaming or the next feature do not push the frame past its deadline.", ch: "11.1" },
    "height-fog": { term: "Height fog", aka: ["exponential height fog","Exponential Height Fog","height-based fog","ground fog"], def: "Fog whose density falls exponentially with height, so it pools near the ground and in valleys and thins towards the sky. The fog along each view ray has a closed-form answer, so it costs one cheap pass.", ch: "9.5" },
    "height-map": { term: "Height map", aka: ["heightmap","displacement map","depth map"], def: "A greyscale texture where brightness means height above the surface. Used to make normal maps, for parallax effects and to displace real geometry.", ch: "6.4" },
    "hi-z": { term: "Hi-Z occlusion culling", aka: ["Hi-Z","HZB","hierarchical Z-buffer","depth pyramid","hierarchical depth"], def: "Occlusion culling against a depth pyramid: a chain of ever smaller copies of the depth buffer in which each texel keeps the farthest depth of the texels it covers. An object is hidden if it is farther than that stored depth across its whole screen footprint.", ch: "4.4" },
    "hi-z-tracing": { term: "Hi-Z tracing", aka: ["Hi-Z screen-space tracing","HZB traversal","hierarchical ray marching","hierarchical depth tracing"], def: "Ray marching through a depth pyramid whose texels keep the nearest depth below them. While a ray stays in front of a cell's nearest surface it skips the whole cell, so it crosses empty space in a few reads without stepping past thin objects.", ch: "8.4" },
    "history-buffer": { term: "History buffer", aka: ["TAA history","accumulation buffer","previous frame buffer"], def: "The image in which a temporal technique keeps its result from the previous frame. The next frame reprojects it and blends in its new samples.", ch: "9.2" },
    "history-rejection": { term: "History rejection", aka: ["history invalidation","Speed rejection","disocclusion detection"], def: "Discarding or down-weighting a pixel's history when it is probably wrong, for example because depth or speed changed sharply or the pixel was just revealed, so the new frame dominates there.", ch: "9.2" },
    "hitch": { term: "Hitch", aka: ["stutter","frame spike","spike"], def: "A frame, or a short run of frames, that takes far longer than the frames around it, so motion visibly freezes or jumps even when the average frame rate looks fine.", ch: "0.2" },
    "hlod": { term: "HLOD", aka: ["hierarchical level of detail","proxy mesh","visibility ranges"], def: "Replacing a whole group of distant objects, such as a city block, with one merged and simplified mesh and material, built offline, so the group costs one draw and a fraction of the triangles.", ch: "4.5" },
    "hlsl": { term: "HLSL", aka: ["High-Level Shader Language","High-Level Shading Language",".usf"], def: "Microsoft's C-like language for writing shaders, used by Direct3D and by Unreal and Unity for every platform. Compilers translate it to the formats other graphics APIs need.", ch: "5.6" },
    "horizon-angle": { term: "Horizon angle", aka: ["horizon"], def: "In one direction from a point, the steepest angle at which surrounding geometry rises above it. Everything below that angle is blocked; everything above is open sky.", ch: "8.3" },
    "hybrid-rendering": { term: "Hybrid rendering", aka: ["hybrid ray tracing","hybrid renderer"], def: "Drawing what the camera sees with rasterization and tracing rays only for effects such as shadows, reflections and bounced light, starting each ray from the G-buffer.", ch: "8.6" },
    "ies-profile": { term: "IES light profile", aka: ["IES profile","IES file","IES Texture","photometric profile","LM-63"], def: "A file from a lamp maker that lists how strong a fixture is in each direction, in the Illuminating Engineering Society's LM-63 format. Engines use it to give lights the shaped beams of real fixtures.", ch: "7.1" },
    "image-based-lighting": { term: "Image-based lighting", aka: ["IBL","environment lighting"], def: "Lighting surfaces from an environment map, treating every texel as light arriving from its direction, instead of only from individual lights. Blurred versions supply rough reflections and soft diffuse light.", ch: "7.6" },
    "immediate-mode-gpu": { term: "Immediate-mode GPU", aka: ["immediate-mode rendering","IMR"], def: "A GPU that draws triangles in the order they arrive and writes each pixel's colour and depth straight to full-screen buffers in memory. Desktop and console GPUs work this way.", ch: "3.5" },
    "importance-sampling": { term: "Importance sampling", aka: ["light sampling","next event estimation","NEE","BRDF sampling","multiple importance sampling","MIS"], def: "Choosing random directions in proportion to how much light they are likely to bring, for example aiming at lights or along a shiny surface's reflection, so fewer samples give less noise.", ch: "8.7" },
    "impostor": { term: "Impostor", aka: ["imposter","impostor card","octahedral impostor"], def: "A picture of an object, rendered ahead of time from one or more directions, drawn on a flat two-triangle card in its place once the object is far away.", ch: "4.5" },
    "in-scattering": { term: "In-scattering", aka: ["inscattering","fog inscattering","single scattering"], def: "Light from the sun, the sky or a lamp that particles along a view ray scatter towards the camera. It is what makes fog, haze and light shafts glow instead of only darkening the view.", ch: "9.5" },
    "incremental-gc": { term: "Incremental garbage collection", aka: ["incremental GC","Use Incremental GC","incremental reachability","gc.AllowIncrementalReachability"], def: "Splitting the garbage collector's work into small slices spread over several frames, so no single frame pays for it all. It does not reduce the total work, and it adds a small cost whenever references change.", ch: "11.3" },
    "index-buffer": { term: "Index buffer", aka: ["IBO","element buffer","element array"], def: "A GPU buffer listing which vertices form each triangle, by row number in the vertex buffer. It lets triangles share corners instead of storing them again.", ch: "4.2" },
    "index-format": { term: "Index format", aka: ["16-bit indices","32-bit indices","UInt16","UInt32"], def: "How many bytes each index uses. 16-bit indices are half the size but can only address 65,536 vertices; bigger meshes need 32-bit indices or splitting.", ch: "4.2" },
    "indirect-drawing": { term: "Indirect drawing", aka: ["indirect draw","DrawIndirect","ExecuteIndirect","multi-draw indirect","MDI"], def: "A draw call whose numbers, such as how many indices and instances to draw, are read from a buffer in GPU memory instead of being supplied by the CPU, so work on the GPU can decide what gets drawn.", ch: "4.3" },
    "indirect-light": { term: "Indirect light", aka: ["bounce light","indirect lighting"], def: "Light that reaches a surface after bouncing off at least one other surface. It is why shadows are rarely pure black.", ch: "8.1" },
    "inline-ray-tracing": { term: "Inline ray tracing", aka: ["ray queries","ray query","RayQuery","TraceRayInline"], def: "Tracing a ray from inside any shader, such as a compute or pixel shader, and handling the result in the same code, without separate hit and miss shaders. Well suited to shadow and occlusion rays.", ch: "8.6" },
    "input-assembler": { term: "Input assembler", aka: ["input assembly","vertex fetch"], def: "The fixed GPU stage that reads the index buffer, fetches the vertex rows it points to and groups them into triangles for the vertex shader.", ch: "5.1" },
    "instance-override": { term: "Override", aka: ["instance override","prefab override"], def: "A value changed on one prefab instance only. It always wins over the prefab's own value, so later edits to that value on the prefab do not reach that instance.", ch: "2.3" },
    "instancing": { term: "GPU instancing", aka: ["instancing","instanced drawing"], def: "Drawing many copies of the same mesh in one draw call, each with its own position and small per-copy data.", ch: "4.3" },
    "interleaved": { term: "Interleaved layout", aka: ["array of structures","AoS"], def: "Storing all of a vertex's attributes next to each other in one row, then the next vertex's row, and so on.", ch: "4.2" },
    "internal-resolution": { term: "Internal resolution", aka: ["render resolution","half resolution"], def: "The resolution an effect or the whole frame is actually computed at, before being scaled to the output. Half resolution means a quarter of the pixels.", ch: "9.3" },
    "interpolator": { term: "Interpolator", aka: ["varying","varyings","vertex output","TEXCOORD","custom interpolator"], def: "A value the vertex shader outputs at each corner, such as a UV or a normal, which the GPU blends across the triangle so every pixel's shader receives its own in-between value.", ch: "5.2" },
    "inverse-square-law": { term: "Inverse-square law", aka: ["inverse-square falloff","inverse squared falloff","Use Inverse Squared Falloff"], def: "The rule that light from a point spreads over an area growing with the square of the distance, so twice as far gets a quarter of the light. Light arriving equals intensity divided by distance squared.", ch: "7.1" },
    "irradiance": { term: "Irradiance", aka: ["E","incident light"], def: "All the light arriving at a point on a surface from every direction above it, each weighted by how squarely it strikes. It decides how bright a matte surface is; illuminance, in lux, is its everyday counterpart.", ch: "8.1" },
    "irradiance-map": { term: "Irradiance map", aka: ["irradiance environment map","diffuse convolution","diffuse environment map"], def: "A version of an environment map storing, for each direction a surface could face, all the light arriving over its half-sphere, weighted by angle. It lights diffuse surfaces and is so blurred that a few texels or numbers hold it.", ch: "7.6" },
    "irradiance-volume": { term: "Irradiance volume", aka: ["probe grid","probe volume","volumetric lightmap","irradiance field"], def: "Light probes arranged in a 3D grid that fills the level, often denser near geometry, so any point in the air can look up baked indirect light by interpolating its neighbours. Unreal's version is the volumetric lightmap.", ch: "8.2" },
    "job-system": { term: "Job system", aka: ["worker threads","task system","task graph","WorkerThreadPool"], def: "An engine service that splits work into small independent jobs and runs them on a pool of worker threads, about one per CPU core, so systems such as animation and physics can use every core.", ch: "2.2" },
    "lambert": { term: "Lambertian diffuse", aka: ["Lambert","Lambert diffuse","Lambertian"], def: "The simplest diffuse model: the surface sends the light it receives equally in all directions, so its brightness depends only on how squarely the light hits. It is the diffuse colour × light × max(N·L, 0) ÷ π.", ch: "7.2" },
    "latency-hiding": { term: "Latency hiding", aka: ["hiding memory latency","warp switching"], def: "How a GPU keeps working while memory requests are in flight: when one warp stops to wait for data, the compute unit switches at no cost to another warp that is ready to run.", ch: "11.2" },
    "lens-distortion": { term: "Lens distortion", aka: ["barrel distortion","pincushion distortion"], def: "Bending of straight lines in the image, outwards (barrel) or inwards (pincushion), as wide or cheap lenses do; applied as a final warp of the image.", ch: "9.4" },
    "lens-flare": { term: "Lens flare", aka: ["lens flares","flare ghosts","Screen Space Lens Flare","Lens Flare (SRP)"], def: "Ghost images and streaks of a bright light, as reflections between a lens's glass elements would make, drawn along a line through the image centre.", ch: "9.4" },
    "level-streaming": { term: "Level streaming", aka: ["world streaming","sublevel streaming","additive scene loading"], def: "Loading and unloading whole pieces of the game world, with their objects, while the game runs, so only the part near the player is in memory.", ch: "11.4" },
    "light-attenuation": { term: "Light attenuation", aka: ["falloff","light falloff","attenuation"], def: "How a light weakens with distance from its source. Physically based engines use the inverse-square law, faded smoothly to zero at the light's attenuation radius.", ch: "7.1" },
    "light-culling": { term: "Light culling", aka: ["light assignment","light binning","light lists"], def: "Working out ahead of shading which lights can reach which part of the screen or which objects, so each pixel only evaluates the lights that touch it.", ch: "7.3" },
    "light-leaking": { term: "Light leaking", aka: ["light leaks","leaks","dark leaking","shadow leaking"], def: "Light appearing where it cannot reach, typically inside a room through a wall, because the GI method stores light more coarsely than the wall is thick. The reverse, darkness leaking into lit areas, has the same cause.", ch: "8.5" },
    "light-mobility": { term: "Light mobility", aka: ["Mobility","Light Mode","Bake Mode","Static","Stationary","Movable","Baked","Mixed","Realtime"], def: "A per-light setting that decides which of its lighting is baked and which is computed every frame. Unreal calls the choices Static, Stationary and Movable, Unity Baked, Mixed and Realtime, and Godot's Bake Mode Static, Dynamic and Disabled.", ch: "8.2" },
    "light-probe": { term: "Light probe", aka: ["Light Probe Group","LightmapProbe","irradiance probe","probe"], def: "A point in empty space where the bake records the light arriving from every direction, usually as a few spherical harmonics numbers. Moving objects between probes blend their values to receive baked bounced light.", ch: "8.2" },
    "light-propagation-volumes": { term: "Light propagation volumes", aka: ["LPV","cascaded light propagation volumes","CLPV"], def: "A real-time GI method from Crytek that injects light from lit surfaces into a coarse 3D grid of spherical harmonics, then spreads it cell to cell over a few iterations. Cheap and fully dynamic, but blurry and prone to light leaking.", ch: "8.5" },
    "light-shafts": { term: "Light shafts", aka: ["god rays","crepuscular rays","sun shafts","volumetric shadows","light beams"], def: "Visible beams of light in hazy air, with darker air where objects cast shadows into it. Rendered by shadowed volumetric fog, or more cheaply by blurring bright pixels outwards from the light's position on screen.", ch: "9.5" },
    "light-space-depth": { term: "Light-space depth", aka: ["light depth","depth from the light"], def: "A point's distance from a light measured along the light's direction, in the shadow map's own coordinates. The shadow test compares it with the depth stored in the shadow map.", ch: "7.4" },
    "light-volume": { term: "Light volume", aka: ["deferred light volume","stencil light volume"], def: "In classic deferred rendering, a simple shape drawn for each light, such as a sphere for a point light, so that only the pixels inside the light's range run its lighting. Each one reads the G-buffer again.", ch: "7.3" },
    "lighting-artist": { term: "Lighting artist", aka: ["lighter"], def: "An artist who places and tunes lights, sky, fog and exposure in a level to create mood and make it readable, within the lighting budget.", ch: "1.2" },
    "lightmap": { term: "Lightmap", aka: [], def: "A texture holding precomputed lighting for static surfaces, laid out with its own UV coordinates.", ch: "8.2" },
    "lightmap-resolution": { term: "Lightmap resolution", aka: ["lightmap texel density","Light Map Resolution","texels per unit","Lightmap Texel Size","Scale In Lightmap"], def: "How many lightmap texels cover each metre of a surface. Doubling it sharpens baked shadows and quadruples the texels, so memory and bake time grow with its square.", ch: "8.2" },
    "lightmap-seam": { term: "Lightmap seam", aka: ["lighting seam","seam artefact","light bleed","padding bleed"], def: "A visible line in baked lighting where two pieces of a lightmap UV layout meet on the model but lie apart in the texture, so their texels disagree. Too little padding between pieces makes light or shadow bleed across the line.", ch: "8.2" },
    "lightmap-uvs": { term: "Lightmap UVs", aka: ["lightmap UV channel","second UV channel","UV2","UV1","Mesh.uv2","Lightmap Coordinate Index"], def: "A second set of texture coordinates in which every face of a mesh has its own space in the lightmap, with no overlaps and a gap of a few texels around each piece. Texture UVs can overlap and repeat; lightmap UVs cannot, because each spot on the surface receives its own light.", ch: "8.2" },
    "lightmapgi": { term: "LightmapGI", aka: ["LightmapGI node","Godot lightmapper"], def: "Godot's node for baked global illumination. It bakes lightmaps on the GPU in the editor and can generate light probes so moving objects receive the baked indirect light.", ch: "8.2" },
    "lightmapper": { term: "Lightmapper", aka: ["light baker","bake","lighting build","Lightmass","GPU Lightmass","Progressive Lightmapper","Unity Compute Light Baker"], def: "The editor tool that computes baked lighting by tracing many light paths from every lightmap texel and probe, then writes the results to textures. A run of it is called a bake or a lighting build.", ch: "8.2" },
    "linear-blend-skinning": { term: "Linear blend skinning", aka: ["LBS","smooth skinning","matrix palette skinning"], def: "The standard skinning method: move a vertex with each of its bones, then average the results by its weights. Fast, but joints lose thickness when they bend or twist far.", ch: "4.6" },
    "linear-colour": { term: "Linear colour", aka: ["linear space","linear light","scene-linear"], def: "Colour values proportional to the amount of light, so twice the number means twice the light. Lighting, blending and blurring only give correct results on linear values.", ch: "3.2" },
    "live-ops": { term: "Live ops", aka: ["live operations","LiveOps","games as a service"], def: "The ongoing work of running a released game: hotfixes, scheduled patches, events, seasons and new content, each one built, tested and released like a small project.", ch: "1.1" },
    "load-action": { term: "Load action", aka: ["load op","loadOp","VK_ATTACHMENT_LOAD_OP","MTLLoadAction","Load, Clear, Don't care"], def: "What a render pass does with an image when it starts: load its old contents from memory, clear it to a value, or start with whatever is there (Don't care). On a tile-based GPU only Load reads memory.", ch: "10.2" },
    "loading-range": { term: "Loading range", aka: ["streaming distance","streaming radius","Loading Range"], def: "The distance from the player, or another streaming source, within which a streaming system keeps the world loaded. A longer range gives loading more time and costs more memory.", ch: "11.4" },
    "local-transform": { term: "Local transform", aka: ["relative transform","localPosition","relative location"], def: "An object's position, rotation and scale measured from its parent. It stays the same when the parent moves.", ch: "2.3" },
    "lod": { term: "Level of detail", aka: ["LOD"], def: "Simpler versions of a mesh swapped in as it gets smaller on screen, so distant objects cost less to draw.", ch: "4.5" },
    "lod-bias": { term: "LOD bias", aka: ["mip bias","mipmap bias","MipLODBias","texture mipmap bias"], def: "A number added to the mip level the GPU would choose. Negative values pick larger, sharper levels at the risk of shimmer; positive values pick smaller, blurrier ones.", ch: "6.2" },
    "lod-cross-fade": { term: "LOD cross-fade", aka: ["dithered LOD transition","LOD dither","cross fade","LOD fade"], def: "Hiding a level-of-detail switch by drawing both levels for a short range or time and handing pixels from one to the other, usually through a dither pattern.", ch: "4.5" },
    "lod-popping": { term: "LOD popping", aka: ["popping","LOD pop"], def: "The visible jump when an object switches from one level of detail to the next in a single frame, seen as a sudden change of outline or shading.", ch: "4.5" },
    "look-development": { term: "Look development", aka: ["look dev","lookdev"], def: "The work of finding and proving a game's visual style inside the engine, through target images, test scenes, materials and lighting, until the look can be repeated across the whole game.", ch: "1.1" },
    "lts": { term: "LTS", aka: ["long-term support"], def: "An engine release that keeps getting bug fixes for an extended period instead of new features. Teams in full production usually stay on one.", ch: "2.4" },
    "lumen": { term: "Lumen", aka: [], def: "Unreal Engine 5's real-time global illumination and reflection system. It computes bounced light, and short-range occlusion, without baking.", ch: "8.5" },
    "lumen-lite": { term: "Lumen Lite", aka: ["Lumen Medium Quality","Irradiance Field Gather","r.Lumen.FinalGatherMethod 0"], def: "Unreal Engine 5.8's medium-quality Lumen, in Beta: global illumination from a field of irradiance probes and screen-space reflections instead of Lumen reflections, about twice as fast as Lumen at High and aimed at Switch 2 and lower-end PCs.", ch: "10.3" },
    "lumen-unit": { term: "Lumen (unit)", aka: ["lm","lumens","luminous flux"], def: "The unit of all the visible light a source gives out, in every direction. A candle gives about 13 lumens and a household bulb 600 to 1,200.", ch: "7.1" },
    "luminance-histogram": { term: "Luminance histogram", aka: ["exposure histogram","histogram metering","Automatic Histogram"], def: "A count of the frame's pixels in brightness bands on a log scale. Auto-exposure uses it to ignore the darkest and brightest pixels before working out the average.", ch: "9.1" },
    "lut": { term: "LUT", aka: ["lookup table","3D LUT","colour lookup table","Color Lookup","Color Grading LUT","lookup texture"], def: "A small 3D texture, typically 16 or 32 entries along each side, that maps every input colour to an output colour, so a whole grade costs one texture read per pixel.", ch: "9.1" },
    "lux": { term: "Lux", aka: ["lx","illuminance","lumens per square metre"], def: "The unit of light arriving on a surface: one lumen per square metre. Direct sunlight gives tens of thousands of lux, a full moon well under one.", ch: "7.1" },
    "magnitude": { term: "Magnitude", aka: ["length","vector length","norm","size"], def: "The length of a vector, found with Pythagoras: the square root of the sum of its squared components. The vector (3, 4) has a magnitude of 5.", ch: "3.3" },
    "manifold": { term: "Manifold", aka: ["watertight","non-manifold","closed mesh"], def: "A mesh whose surface could be the skin of a real object, with every edge shared by at most two faces. Non-manifold geometry, such as three faces on one edge, confuses tools that need a clear inside and outside.", ch: "4.1" },
    "mass-entity": { term: "Mass Entity", aka: ["Mass","MassEntity","Mass AI"], def: "Unreal Engine's data-oriented framework for large numbers of similar things, such as crowds and traffic. Its components are called fragments and its systems processors.", ch: "2.3" },
    "material": { term: "Material", aka: ["material asset","StandardMaterial3D","Lit material"], def: "The description of how a surface treats light: a shader plus the textures and values that feed it, such as base colour, metallic and roughness.", ch: "6.5" },
    "material-instance": { term: "Material instance", aka: ["Material Instance","Material Variant","material override","MIC","MID"], def: "A copy of a parent material that reuses its compiled shader with different parameter values, such as another tint or texture. Instances are cheap because nothing is recompiled.", ch: "6.5" },
    "material-sorting": { term: "Material sorting", aka: ["state sorting","draw sorting","sort key"], def: "Ordering a pass's draw calls so that draws sharing a shader, then a material, then a mesh run one after another, which cuts the number of state changes between them.", ch: "4.3" },
    "matrix": { term: "Matrix", aka: ["matrices","4×4 matrix","transformation matrix","float4x4"], def: "A grid of numbers, usually 4 by 4 in graphics, that stores a transform. Multiplying a position by it applies the transform, and multiplying matrices together chains transforms into one.", ch: "3.4" },
    "max-bone-influences": { term: "Bone influences per vertex", aka: ["max influences","bones per vertex","Max Bones/Vertex","Skin Weights quality"], def: "The most bones allowed to move one vertex, commonly 4, sometimes 8 or more. Extra influences are dropped and the rest rescaled, which can stiffen complex joints.", ch: "4.6" },
    "megalights": { term: "MegaLights", aka: ["r.MegaLights","MegaLights Shadow Method"], def: "Unreal Engine 5's stochastic direct lighting: each pixel traces a fixed number of rays towards the lights most likely to matter and a denoiser fills in the rest, so cost stays roughly constant as lights are added while quality drops where many lights overlap. It needs hardware ray tracing.", ch: "10.3" },
    "memory-bandwidth": { term: "Memory bandwidth", aka: ["bandwidth","GB/s"], def: "How many bytes per second a memory can deliver to the processors reading it. Many rendering passes are limited by it more than by arithmetic, and on phones it costs battery and heat.", ch: "3.5" },
    "memory-budget": { term: "Memory budget", aka: ["RAM budget","memory map","memory plan"], def: "How much memory a game may use on each platform, split between its systems such as render targets, textures, meshes, audio and gameplay, with some kept back. Every system is measured against its share.", ch: "11.4" },
    "memory-fragmentation": { term: "Memory fragmentation", aka: ["fragmentation","heap fragmentation"], def: "Free memory broken into gaps between objects that are each too small for a large request, so an allocation can fail while the total free is far larger. It grows over long sessions.", ch: "11.4" },
    "memoryless-attachment": { term: "Memoryless attachment", aka: ["memoryless","MTLStorageModeMemoryless","transient attachment","VK_IMAGE_USAGE_TRANSIENT_ATTACHMENT_BIT","lazily allocated memory"], def: "A render target that exists only in tile memory for one render pass and has no copy in main memory, such as a depth buffer or MSAA samples that nothing reads later. Metal calls it memoryless; Vulkan uses transient attachments in lazily allocated memory.", ch: "10.2" },
    "merged-mesh": { term: "Merged mesh", aka: ["combined mesh","mesh merging","Merge Actors"], def: "Several objects joined into one mesh asset, by hand or with a tool, so they draw as one object with one draw call per material. It is then culled, loaded and drawn as one piece.", ch: "4.3" },
    "mesh": { term: "Mesh", aka: ["model","geometry"], def: "The shape of an object as a set of triangles joined at shared corners, plus the per-corner data needed to draw it.", ch: "4.1" },
    "mesh-lod-bias": { term: "LOD bias (meshes)", aka: ["LOD Bias","lodBias","lod_bias","LOD distance scale"], def: "A setting that moves every level-of-detail switch point at once, so the same scene uses more or less detail. In Unity and Godot, values above 1 keep detailed levels farther away.", ch: "4.5" },
    "mesh-shader": { term: "Mesh shader", aka: ["amplification shader","task shader","object shader","mesh shading"], def: "A newer kind of shader that replaces the input assembler and vertex shader. Each group of threads loads a small chunk of a mesh from any buffer and outputs a batch of triangles straight to the rasterizer, optionally after a task or amplification shader has culled whole chunks.", ch: "5.1" },
    "mesh-simplification": { term: "Mesh simplification", aka: ["decimation","polygon reduction","mesh reduction","auto LOD"], def: "Making a version of a mesh with fewer triangles automatically, usually by collapsing edges one at a time in the order that changes the shape least.", ch: "4.5" },
    "mesh-streaming": { term: "Mesh streaming", aka: ["geometry streaming","LOD streaming","Nanite streaming"], def: "Loading the detailed levels of detail of meshes, or clusters of their triangles, only when the camera is close enough to need them, and freeing them afterwards.", ch: "11.4" },
    "meshlet": { term: "Meshlet", aka: ["cluster"], def: "A small chunk of a mesh, typically 64 to 128 triangles, that modern renderers cull and process as a unit.", ch: "4.5" },
    "metal": { term: "Metal", aka: ["Metal 4"], def: "Apple's graphics API for Mac, iPhone, iPad and Vision Pro, and the only modern API native to them.", ch: "3.5" },
    "metal-roughness": { term: "Metal/roughness workflow", aka: ["metallic/roughness","metalness workflow","Metallic workflow"], def: "The standard way to author PBR materials, with base colour, metallic and roughness inputs. The shader derives the diffuse colour and F0, so no values from 0 to 1 can break physics.", ch: "6.5" },
    "metallic": { term: "Metallic", aka: ["metalness","metal mask","Metallic Map"], def: "A material input that says whether a surface is a metal (1) or not (0). Metals have no diffuse colour and tint their reflections with the base colour; in-between values are only for blends.", ch: "6.5" },
    "microfacet": { term: "Microfacets", aka: ["microfacet model","microsurface"], def: "The model of a surface as countless tiny flat mirrors, each tilted slightly and far smaller than a pixel. How much they disagree in direction decides how sharp or blurred reflections are.", ch: "6.5" },
    "middle-grey": { term: "Middle grey", aka: ["mid-grey","18% grey","key value","Target Mid Gray"], def: "A surface reflecting 18% of the light, which looks halfway between black and white. Exposure aims to show a scene's average brightness at about this level.", ch: "9.1" },
    "mie-scattering": { term: "Mie scattering", aka: ["Mie","aerosol scattering"], def: "Scattering by particles about as large as the wavelength of light or larger, such as dust, pollution and water droplets. It affects all colours about equally and points strongly forwards, giving white haze and the bright glow around the sun.", ch: "9.5" },
    "mikktspace": { term: "MikkTSpace", aka: ["Mikktspace","Calculate Mikktspace","synced tangent space"], def: "A standard way of computing a mesh's tangents, by Morten Mikkelsen, that gives the same result in every tool. When the baker and the engine both use it, baked normal maps decode without seams.", ch: "6.4" },
    "milestone": { term: "Milestone", aka: ["gate","milestone review"], def: "A dated checkpoint where the team delivers a build and evidence, and the people funding the game decide whether to continue. Its criteria should be agreed at the start of the phase it closes.", ch: "1.1" },
    "min-spec": { term: "Minimum specification", aka: ["min spec","minimum requirements","minimum system requirements"], def: "The least powerful hardware a PC game promises to run on, at its lowest settings. It should be a machine the team has actually tested.", ch: "1.4" },
    "mip-level-selection": { term: "Mip level selection", aka: ["texture LOD","mip selection","lambda"], def: "How the GPU picks a mip level for each pixel: it measures how many texels the pixel spans from the UV differences between neighbouring pixels and takes log2 of that span.", ch: "6.2" },
    "mip-streaming": { term: "Mip streaming", aka: ["Mipmap Streaming","mipmap streaming","mip-level streaming"], def: "The common form of texture streaming: for each texture, keep in memory only the mip levels its nearest visible use needs, and load sharper levels from disk as the camera approaches.", ch: "6.3" },
    "mipmap": { term: "Mipmap", aka: ["mip chain","mips","mip level","MIP map"], def: "A chain of copies of a texture, each half the width and height of the one before, down to 1 × 1. The GPU reads the copy that best matches each pixel's size, and the chain adds a third to the texture's memory.", ch: "6.2" },
    "model-matrix": { term: "Model matrix", aka: ["world matrix","object-to-world matrix","local-to-world matrix","M"], def: "The matrix that takes an object's vertices from object space into world space. It is built from the object's position, rotation and scale.", ch: "3.4" },
    "monte-carlo-integration": { term: "Monte Carlo integration", aka: ["Monte Carlo","random sampling","stochastic sampling","Monte Carlo estimator"], def: "Estimating an average, such as all the light arriving at a point, from random samples. The error shrinks with the square root of the number of samples, so halving it takes four times as many.", ch: "8.7" },
    "motion-blur": { term: "Motion blur", aka: ["camera motion blur","object motion blur","per-object motion blur"], def: "Smearing each pixel along its motion vector, as a real shutter does while things move, so motion looks smoother. Camera blur comes from the camera's movement; object blur from each object's own.", ch: "9.4" },
    "motion-vectors": { term: "Motion vectors", aka: ["velocity buffer","velocities","motion vector buffer","MVs","Output Velocity"], def: "A screen-sized buffer holding, for each pixel, how far its surface moved on screen since the last frame. Temporal anti-aliasing, upscalers and motion blur all read it.", ch: "9.2" },
    "mrt": { term: "Multiple render targets", aka: ["MRT","MRTs"], def: "Writing several images at once from one pixel shader, such as base colour, normals and roughness into separate render targets. Deferred renderers fill their G-buffer this way in a single pass.", ch: "7.3" },
    "msaa": { term: "MSAA", aka: ["multisample anti-aliasing","MSAA 4x","multisampling","MSAA resolve"], def: "Multisample anti-aliasing: the GPU tests coverage and depth at several points per pixel but runs the pixel shader about once per pixel per triangle, then averages the samples. It smooths geometry edges only.", ch: "9.2" },
    "multi-bounce-ao": { term: "Multi-bounce AO", aka: ["multi-bounce approximation"], def: "A correction that brightens AO on light-coloured surfaces, because light bounces several times in a bright crease before it is absorbed.", ch: "8.3" },
    "mvp": { term: "MVP matrix", aka: ["model-view-projection","WorldViewProjection","WVP"], def: "The model, view and projection matrices multiplied into one, so a vertex shader can take a vertex from object space to clip space in a single multiply.", ch: "3.4" },
    "n-dot-l": { term: "N·L", aka: ["N dot L","NdotL","NoL","cosine term","Lambert's cosine law"], def: "The dot product of the surface normal and the direction to the light, which equals the cosine of the angle between them. It measures how squarely light lands: 1 head-on, 0 edge-on, and clamped to 0 when the light is behind.", ch: "7.2" },
    "nanite": { term: "Nanite", aka: ["virtualized geometry"], def: "Unreal Engine 5's geometry system. It splits meshes into clusters and streams and draws only the detail each part of the screen needs.", ch: "4.5" },
    "nanite-fallback-mesh": { term: "Fallback mesh", aka: ["Nanite fallback mesh","Fallback Relative Error","Fallback Target"], def: "A simplified ordinary mesh that Unreal builds from each Nanite mesh for the places Nanite's own format is not used, most importantly the ray tracing scene. How detailed it is can be set per mesh.", ch: "10.3" },
    "ndc": { term: "Normalised device coordinates", aka: ["NDC","normalized device coordinates"], def: "Clip-space positions after the divide by w. Everything visible lies between -1 and 1 across and up, and inside a fixed depth range, whatever the size of the screen.", ch: "3.4" },
    "near-plane": { term: "Near plane", aka: ["near clip plane","near clipping plane","znear"], def: "The distance in front of the camera where drawing starts; anything closer is cut away. It has a large effect on depth precision, so it should be as far out as the game allows.", ch: "3.4" },
    "nearest-filtering": { term: "Nearest filtering", aka: ["point filtering","point sampling","nearest-neighbour","Point (no filter)"], def: "Reading only the single texel closest to the sample point. It is the cheapest filter: magnified texels show as hard blocks and distant textures shimmer.", ch: "6.2" },
    "neighbourhood-clamping": { term: "Neighbourhood clamping", aka: ["neighborhood clamping","history clamping","colour clamping","variance clipping","Variance Clamp Scale"], def: "Limiting a pixel's reprojected history to the range of colours in its 3 by 3 neighbourhood in the current frame, so stale history that no longer fits, such as a ghost, is pulled back.", ch: "9.2" },
    "ngon": { term: "N-gon", aka: ["ngon","polygon"], def: "A face with more than four corners. Modelling tools allow them, but each tool may split them into triangles differently, so they often cause shading and baking surprises.", ch: "4.1" },
    "nit": { term: "Nit", aka: ["nits","cd/m²","candela per square metre"], def: "The unit of screen brightness: one candela per square metre. Standard screens show white at roughly 100 to 300 nits; HDR screens reach 400 to 1,000 nits or more in highlights.", ch: "3.2" },
    "noise": { term: "Sampling noise", aka: ["noise","grain"], def: "Random speckle in an effect that was computed from too few samples per pixel. More samples, or denoising, removes it.", ch: "8.7" },
    "normal": { term: "Normal", aka: ["surface normal","vertex normal"], def: "A direction pointing straight out of a surface. Lighting uses it to work out how directly light hits that point.", ch: "4.1" },
    "normal-map": { term: "Normal map", aka: ["normal texture","tangent-space normal map"], def: "A texture that stores a surface direction for every texel as red, green and blue. Lighting reads it per pixel, so flat triangles shade as if they had bumps, grooves and scratches.", ch: "6.4" },
    "normal-offset": { term: "Normal offset", aka: ["normal bias","normal offset shadows"], def: "Moving a point a fraction of a texel along its surface normal before the shadow test, or shrinking casters along theirs, which removes acne on tilted surfaces with less detachment than a large depth bias.", ch: "7.4" },
    "object-pooling": { term: "Object pooling", aka: ["pooling","object pool","UnityEngine.Pool"], def: "Keeping a set of frequently used objects, such as projectiles or effects, alive and reusing them instead of creating and destroying them, which avoids allocation, garbage collection and set-up costs.", ch: "11.3" },
    "object-space": { term: "Object space", aka: ["model space","local space","mesh space"], def: "Coordinates measured from a model's own origin, the way the artist built it. Vertex buffers store positions in object space.", ch: "3.4" },
    "object-space-normal-map": { term: "Object-space normal map", aka: ["object space normal map","model-space normal map","world-space normal map"], def: "A normal map whose directions are relative to the whole model rather than to the surface. It needs no tangents, but works only on the mesh it was made for and cannot tile, mirror or deform.", ch: "6.4" },
    "occludee": { term: "Occludee", aka: ["Occludee Static"], def: "An object that occlusion culling tests and may skip because occluders hide it. Small and medium objects are usually occludees only.", ch: "4.4" },
    "occluder": { term: "Occluder", aka: ["Occluder Static","OccluderInstance3D"], def: "An object used to hide others during occlusion culling, usually a large solid one such as a wall, a building or terrain. Engines often use simplified occluder shapes.", ch: "4.4" },
    "occlusion-culling": { term: "Occlusion culling", aka: ["OC","occlusion queries","hardware occlusion queries","dynamic occlusion"], def: "Skipping objects that are inside the view but completely hidden behind other objects, such as buildings or walls.", ch: "4.4" },
    "off-screen-miss": { term: "Off-screen miss", aka: ["ray left the screen","screen-edge miss"], def: "A screen-space ray that leaves the frame, or passes behind the camera, before it hits anything. The depth buffer has no data there, so a fallback must answer.", ch: "8.4" },
    "oit": { term: "Order-independent transparency", aka: ["OIT","per-pixel sorting","weighted blended OIT","depth peeling"], def: "Techniques that blend transparent layers correctly per pixel whatever order they are drawn in, either by storing and sorting every layer or by approximating the result in one pass.", ch: "5.5" },
    "on-tile-resolve": { term: "On-tile resolve", aka: ["MSAA resolve on tile","inline resolve","multisampleResolve","resolve attachment","pResolveAttachments"], def: "Averaging MSAA samples into one colour per pixel as each finished tile is written out, so the samples never reach main memory. It makes MSAA cheap on tile-based GPUs; a separate resolve pass throws the saving away.", ch: "10.2" },
    "one-percent-low": { term: "1% low", aka: ["1% lows","1% low fps","0.1% low","99th percentile frame time","P1"], def: "The frame rate of a run's slowest frames: in NVIDIA's FrameView, the average of the slowest 1% of frames, while other tools report the frame rate that 99% of frames beat. Far below the average, it reveals stutter the average hides.", ch: "11.1" },
    "open-source": { term: "Open source", aka: ["FOSS","MIT licence"], def: "Software whose source anyone may use, change and redistribute under a licence such as MIT. Godot is open source, and games made with it belong to their makers.", ch: "2.4" },
    "opengl": { term: "OpenGL", aka: ["OpenGL ES","GLES","WebGL","GL"], def: "The older cross-platform graphics API, with OpenGL ES on phones and WebGL in browsers as its cut-down relatives. Still widely supported, but replaced by Vulkan, Metal and DirectX 12 for new work on most platforms.", ch: "3.5" },
    "orthographic-projection": { term: "Orthographic projection", aka: ["orthographic","ortho","orthogonal","parallel projection"], def: "A projection in which lines of sight run parallel, so things keep their size at any distance. Used for 2D games, UI, top-down strategy views and directional-light shadows.", ch: "3.4" },
    "out-of-memory": { term: "Out of memory", aka: ["OOM","OOM crash","allocation failure"], def: "A request for memory that cannot be met. On consoles there is no paging to fall back on, so the game usually crashes.", ch: "11.4" },
    "output-merger": { term: "Output merger", aka: ["ROP","render output unit","raster operations","OM"], def: "The fixed last stage of the pipeline. It tests each shaded pixel's depth against the depth buffer, then writes or blends its colour into the image being drawn. The hardware units that do this are often called ROPs.", ch: "5.1" },
    "overdraw": { term: "Overdraw", aka: ["overshading","overdraw count"], def: "Shading the same pixel more than once in a frame because several surfaces cover it. An average overdraw of 3 means three pixel shader runs for every pixel on screen.", ch: "5.4" },
    "parallax-mapping": { term: "Parallax mapping", aka: ["offset mapping","Bump Offset","virtual displacement mapping"], def: "Shifting each pixel's texture lookup by an amount taken from a height map and the viewing angle, so deep detail seems to move correctly with the camera. One extra texture read; it breaks down at grazing angles.", ch: "6.4" },
    "parallelism": { term: "Parallelism", aka: ["parallel processing","data parallelism"], def: "Doing many pieces of the same job at the same time instead of one after another. GPUs are built for it: thousands of lanes each work on their own vertex or pixel at once.", ch: "3.5" },
    "participating-media": { term: "Participating media", aka: ["participating medium","volumetric media","medium"], def: "Anything light travels through that scatters or absorbs some of it on the way, such as air, haze, fog, smoke, cloud or murky water.", ch: "9.5" },
    "particle-system": { term: "Particle system", aka: ["particles","emitter","particle effect","Niagara system","Particle System","VFX"], def: "An effect made of many small, short-lived elements, such as sparks, smoke puffs or raindrops, that an emitter spawns, moves every frame by simple rules and draws, usually as camera-facing cards.", ch: "9.6" },
    "pass-ordering": { term: "Pass ordering", aka: ["pass order","render order","frame order"], def: "The order in which a frame's passes run. A pass must come after every pass whose output it reads; passes that do not read each other's output can be reordered or run at the same time.", ch: "10.1" },
    "path-tracing": { term: "Path tracing", aka: ["path tracer","full ray tracing","Monte Carlo path tracing"], def: "Rendering by following random paths from the camera, bounce after bounce, until they reach light, and averaging many paths per pixel. With enough samples it converges to the correct image, every bounce included.", ch: "8.7" },
    "pbr": { term: "Physically based rendering", aka: ["PBR","physically based shading","PBS"], def: "Rendering in which materials state measurable properties of a surface and lights follow real physics, so the same asset looks right under any lighting.", ch: "6.5" },
    "pcf": { term: "Percentage-closer filtering", aka: ["PCF","shadow filtering"], def: "Softening shadow edges by running the shadow test against several nearby texels and averaging the answers, so a pixel can be partly lit. It averages comparisons, never the depths themselves.", ch: "7.4" },
    "pcss": { term: "Percentage-closer soft shadows", aka: ["PCSS","contact-hardening shadows","contact hardening"], def: "A shadow filter that estimates how far each pixel is from its blocker and widens the PCF kernel with that distance, so shadows are sharp where objects touch and softer further away.", ch: "7.4" },
    "per-frame-allocation": { term: "Per-frame allocation", aka: ["GC.Alloc","allocation churn","garbage per frame","GC Allocated In Frame"], def: "Memory a game allocates in every frame of ordinary play, such as temporary strings, lists or closures. In a garbage-collected language each byte brings the next collection closer.", ch: "11.3" },
    "per-instance-data": { term: "Per-instance data", aka: ["instance buffer","instance data","Per Instance Custom Data"], def: "The small row of numbers each copy gets in an instanced draw, usually its transform and perhaps a tint. Shaders read it by instance number, so copies of one mesh can differ.", ch: "4.3" },
    "per-light-cost": { term: "Per-light cost", aka: ["light count","light complexity","light budget"], def: "The GPU time each dynamic light adds: roughly the pixels it reaches times the shading work for each, plus any shadow maps it renders. It is why projects budget overlapping and shadow-casting lights.", ch: "7.1" },
    "per-vertex-lighting": { term: "Per-vertex lighting", aka: ["vertex lighting","Gouraud shading"], def: "Running the lighting only at each vertex and blending the results across the triangle. It is cheaper than lighting every pixel, but highlights smear or vanish on large triangles.", ch: "7.2" },
    "perforce": { term: "Perforce", aka: ["P4","Helix Core","p4"], def: "A version control system built for very large binary files and large teams, with file locking. Its server, long called Helix Core, is now named P4.", ch: "1.3" },
    "perspective-aliasing": { term: "Perspective aliasing", aka: ["shadow aliasing near the camera"], def: "Blocky shadows near the camera caused by a shadow map whose texels are all the same size while screen pixels cover more ground the further away they are. Near the camera, many pixels share one shadow texel.", ch: "7.5" },
    "perspective-correct-interpolation": { term: "Perspective-correct interpolation", aka: ["perspective correction","affine interpolation","affine texture mapping"], def: "Blending vertex values so they follow the 3D surface rather than the flat screen, by dividing by depth before blending. Without it, called affine interpolation, textures bend and swim on surfaces that lean away from the camera.", ch: "5.3" },
    "perspective-divide": { term: "Perspective divide", aka: ["divide by w","homogeneous divide","w-divide"], def: "The step after the vertex shader where the GPU divides a clip-space position's x, y and z by its w. With a perspective projection w grows with distance, which is what makes far things smaller.", ch: "3.4" },
    "perspective-projection": { term: "Perspective projection", aka: ["perspective"], def: "A projection in which lines of sight meet at the camera, so distant things look smaller. The usual choice for 3D views.", ch: "3.4" },
    "peter-panning": { term: "Peter-panning", aka: ["shadow detachment","floating shadows"], def: "Shadows that start some distance from the object casting them, so it seems to float. It comes from too much shadow bias or normal offset and shows first on thin objects such as walls and legs.", ch: "7.4" },
    "phase-function": { term: "Phase function", aka: ["anisotropy","Anisotropy","Scattering Distribution","Henyey-Greenstein","g","Mie Anisotropy"], def: "How much light a particle scatters in each direction relative to where the light came from. Haze and fog scatter mostly forwards, so they glow brightest when you look towards the light; one number, g, sets how strongly.", ch: "9.5" },
    "phong": { term: "Phong reflection model", aka: ["Phong","Phong specular"], def: "An early shading model (Bui Tuong Phong, 1975) whose highlight measures how close the light's mirror direction is to the view direction, raised to a shininess exponent. Not to be confused with Phong shading, which means interpolating normals across a triangle.", ch: "7.2" },
    "physical-light-units": { term: "Physical light units", aka: ["photometric units","PLU","real-world light units"], def: "Light intensities given in real units such as lumens, candelas, lux and nits, so engine values can be compared with real lamps, daylight and light meters.", ch: "7.1" },
    "physics-engine": { term: "Physics engine", aka: ["physics","Chaos","PhysX","Jolt"], def: "The engine system that moves objects under forces such as gravity, and detects and resolves collisions between them.", ch: "2.1" },
    "physics-interpolation": { term: "Physics interpolation", aka: ["interpolation","Rigidbody interpolation"], def: "Drawing each moving object part-way between its last two physics steps, according to how far the current frame lies between them, so motion stays smooth when physics and rendering run at different rates.", ch: "2.2" },
    "pipeline-stage": { term: "Pipeline stage", aka: ["stage"], def: "One step of the graphics pipeline, with a fixed input and output. All stages work at the same time on different triangles and pixels, so the slowest one sets the pace.", ch: "5.1" },
    "pipelining": { term: "Pipelining", aka: ["frame pipelining","parallel rendering"], def: "Working on several frames at once in different stages, like an assembly line: the game thread updates one frame while the render thread prepares the one before and the GPU draws the one before that.", ch: "2.2" },
    "pixel": { term: "Pixel", aka: [], def: "One dot of the final image. A 1920 by 1080 frame has about 2.07 million of them.", ch: "3.1" },
    "pixel-coverage": { term: "Pixel coverage", aka: ["coverage","coverage test","inside test"], def: "Whether a triangle covers a pixel, decided by testing the pixel's sample point against the triangle's three edges. A pixel is either fully in or fully out.", ch: "5.3" },
    "pixel-quad": { term: "Pixel quad", aka: ["2×2 quad","quad","helper lane","helper pixel","helper invocation"], def: "A 2 by 2 block of pixels that the GPU always shades together, so the shader can compare neighbours. Pixels in the block that the triangle does not cover still run, as helper lanes, and their results are thrown away.", ch: "5.4" },
    "pixel-shader": { term: "Pixel shader", aka: ["fragment shader"], def: "The GPU program that runs for every pixel a triangle covers and decides that pixel's colour.", ch: "5.4" },
    "pixels-per-triangle": { term: "Pixels per triangle", aka: ["triangle density","triangle size on screen"], def: "The pixels an object covers on screen divided by the triangles drawn for it. As it falls toward one or less, extra triangles add no visible detail and the GPU wastes work on them.", ch: "4.5" },
    "planar-reflection": { term: "Planar reflection", aka: ["Planar Reflection Probe","mirror reflection","planar reflections"], def: "An exact reflection for a flat surface made by rendering the scene again from a camera mirrored below the plane. It sees everything, including off-screen objects, at the cost of a second scene render.", ch: "7.6" },
    "platform": { term: "Platform", aka: ["target platform","target"], def: "Everything a game runs on and sells through: the hardware, its operating system, its store and its owner's rules. PS5, Windows PCs, Android phones and web browsers are platforms.", ch: "1.4" },
    "platform-holder": { term: "Platform holder", aka: ["platform owner","first party","console manufacturer"], def: "The company that controls a closed platform and its store, such as Sony, Microsoft, Nintendo or Meta, and decides which games may be sold on it.", ch: "1.4" },
    "platform-layer": { term: "Platform layer", aka: ["platform abstraction layer","HAL","OS layer"], def: "The bottom layer of an engine that wraps each operating system's way of opening windows, reading controllers, accessing files, keeping time and starting threads, so the rest of the engine does not care which platform it runs on.", ch: "2.1" },
    "plugin": { term: "Plugin", aka: ["module","package","addon","extension","GDExtension"], def: "A self-contained bundle of code and content that adds a feature to an engine without changing the engine itself. Engines split their own code into modules the same way, so features can be included or left out of each build.", ch: "2.1" },
    "point": { term: "Point", aka: ["position","location"], def: "A place, measured from an origin. Subtracting one point from another gives the vector between them, and adding a vector to a point moves it; adding two points together means nothing.", ch: "3.3" },
    "point-light": { term: "Point light", aka: ["omni light","OmniLight3D","Point Light","punctual light"], def: "A light that shines equally in all directions from a single point, like a bare bulb. Its light weakens with the square of the distance.", ch: "7.1" },
    "polygon-count": { term: "Polygon count", aka: ["poly count","polycount","triangle count","tri count"], def: "How many triangles a mesh or a whole frame contains. Teams set budgets per asset and per frame for each platform, because every triangle costs vertex work, memory and shading efficiency.", ch: "4.1" },
    "pom": { term: "Parallax occlusion mapping", aka: ["POM","Deep Parallax","pixel displacement"], def: "Stepping along the view ray through a height map in every pixel until it meets the surface, so raised detail shifts with the view and hides what is behind it. Costs several to dozens of texture reads per pixel.", ch: "6.4" },
    "portal-culling": { term: "Portal culling", aka: ["cells and portals","portals","rooms and portals","Occlusion Portal"], def: "Visibility for indoor levels split into rooms (cells) joined by openings (portals). The renderer only looks into other rooms through the portals the camera can see, narrowing the view at each one.", ch: "4.4" },
    "post-process-aa": { term: "Post-process anti-aliasing", aka: ["morphological anti-aliasing","MLAA","screen-space anti-aliasing","Screen Space AA","post AA"], def: "Anti-aliasing that works on the finished image: it finds edges by contrast and blends pixels along them. It is cheap and works with any renderer, and cannot recover detail the frame never sampled.", ch: "9.2" },
    "post-process-volume": { term: "Post-process volume", aka: ["Post Process Volume","Volume","Volume override","Volume Profile","WorldEnvironment"], def: "A box in the level, or a global setting, that holds values for post-processing effects. The engine blends the values of overlapping volumes as the camera moves through them.", ch: "9.4" },
    "post-processing": { term: "Post-processing", aka: ["post effects","post-process","post FX","full-screen effects"], def: "Full-screen passes that run after the scene is lit, reading the lit image plus buffers such as depth and motion vectors and writing a new image: bloom, depth of field, motion blur, tone mapping and the like.", ch: "9.4" },
    "power-budget": { term: "Power budget", aka: ["thermal budget","TDP"], def: "How much electrical power a device can draw and how much heat it can shed. It limits sustained performance far more tightly on phones and headsets than on consoles and PCs.", ch: "1.4" },
    "power-of-two": { term: "Power-of-two size", aka: ["POT","power of 2","NPOT","non-power-of-two"], def: "A texture side of 256, 512, 1024, 2048 or another power of two. Such textures halve cleanly into smaller copies and suit compressed formats, so engines often pad or scale other sizes on import.", ch: "6.1" },
    "pre-production": { term: "Pre-production", aka: ["preproduction"], def: "The phase after concept where a small team tests the riskiest ideas, proves the look and the pipeline, sets budgets and plans the rest of the project. It usually ends with a vertical slice.", ch: "1.1" },
    "precomputed-realtime-gi": { term: "Precomputed real-time GI", aka: ["Enlighten","Enlighten Realtime Global Illumination","Realtime GI"], def: "GI that precomputes how much static surface patches see each other, then solves bounced light from moving or changing lights at run time, over several frames. Enlighten is the best-known version; geometry cannot move.", ch: "8.5" },
    "prefab": { term: "Prefab", aka: ["Blueprint class","packed scene","template"], def: "A saved, reusable object with its components and children that can be placed many times. Editing the prefab updates every placed copy.", ch: "2.3" },
    "prefab-instance": { term: "Prefab instance", aka: ["instance","instanced scene"], def: "One placed copy of a prefab. It stays linked to the prefab, so it picks up changes made to it.", ch: "2.3" },
    "prefab-variant": { term: "Prefab variant", aka: ["inherited scene","child Blueprint"], def: "A prefab based on another prefab that changes some of its values and inherits the rest, such as a mossy crate made from the plain one.", ch: "2.3" },
    "prefiltered-environment-map": { term: "Prefiltered environment map", aka: ["prefiltered cubemap","radiance map","specular convolution","convolved cubemap"], def: "An environment map whose mip levels hold ever blurrier copies, one per roughness, so a rough surface can read its blurred reflection in a single lookup.", ch: "7.6" },
    "premultiplied-alpha": { term: "Premultiplied alpha", aka: ["premultiply","AlphaComposite","associated alpha"], def: "Storing colour already multiplied by its alpha, and blending with new + (1 − alpha) × old. It filters without dark or bright halos and lets one blend mode act as either normal or additive blending.", ch: "5.5" },
    "present": { term: "Present", aka: ["Present()","vkQueuePresentKHR","flip","swap"], def: "The call that hands a finished frame to the display system, moving it to the front of the swap chain at the next allowed moment.", ch: "3.1" },
    "primitive-assembly": { term: "Primitive assembly", aka: ["triangle assembly","clipping and culling"], def: "The fixed step after the vertex shader that joins shaded corners into triangles, drops triangles facing away from the camera, and clips away what lies outside the view.", ch: "5.1" },
    "producer": { term: "Producer", aka: ["project manager"], def: "The person who plans and tracks the work: schedule, scope, priorities and who does what next. The creative and technical decisions inside the plan belong to the leads.", ch: "1.2" },
    "production": { term: "Production", aka: ["full production"], def: "The main phase of development, when the full team builds the game's features and content to the plan and budgets set in pre-production.", ch: "1.1" },
    "profiler": { term: "Frame capture tool", aka: ["profiler","RenderDoc","PIX on Windows"], def: "A tool that records one frame so you can inspect every draw call, buffer and texture, and how long each pass took.", ch: "11.5" },
    "programmable-stage": { term: "Programmable stage", aka: ["shader stage"], def: "A pipeline stage that runs a shader written for the game, such as the vertex shader or the pixel shader.", ch: "5.1" },
    "projection-matrix": { term: "Projection matrix", aka: ["P","camera projection"], def: "The matrix that takes view-space positions into clip space. It holds the field of view, aspect ratio and near and far planes, and makes the view perspective or orthographic.", ch: "3.4" },
    "prototype": { term: "Prototype", aka: [], def: "A quick, disposable build made to answer one question, such as whether a mechanic is fun or whether an effect can run on the target hardware.", ch: "1.1" },
    "pso": { term: "Pipeline state object", aka: ["PSO","pipeline","graphics pipeline"], def: "A bundle of compiled shaders plus the fixed GPU settings they run with, such as vertex layout, blend, depth and stencil state and target formats. Modern APIs need one for each combination a draw uses, created in advance.", ch: "5.6" },
    "pso-cache": { term: "PSO cache", aka: ["pipeline cache","PSO precaching","shader warm-up","prewarming","bundled PSO cache"], def: "Ways of creating pipeline state objects before they are needed and keeping the results on disk, so later runs and later draws do not stall on compilation.", ch: "5.6" },
    "pvs": { term: "Potentially visible set", aka: ["PVS","precomputed visibility","visibility cells"], def: "For each region of a level, a list computed ahead of time of every object that could be seen from somewhere in it. At runtime the camera's region gives the list, and nothing else needs testing.", ch: "4.4" },
    "qa": { term: "QA", aka: ["quality assurance","tester","QA tester"], def: "Quality assurance: the people who test every build, find and report bugs, check fixes and confirm the game works on each target platform.", ch: "1.2" },
    "quad": { term: "Quad", aka: ["quadrilateral","quad modelling","quad topology"], def: "A four-sided face. Artists model mostly in quads because they form clean rows of edges that are easy to select, edit and subdivide; each becomes two triangles on export.", ch: "4.1" },
    "quad-overdraw": { term: "Quad overdraw", aka: ["quad overshading","Quad Overdraw view"], def: "Extra pixel shader runs caused by 2 by 2 quads that triangles only partly cover, especially along shared edges and on small or thin triangles.", ch: "5.4" },
    "quality-mode": { term: "Upscaler quality mode", aka: ["quality mode","quality preset","Quality","Balanced","Performance","Ultra Performance","DLAA","Native AA"], def: "A named ratio between display and internal resolution per axis, such as Quality at 1.5 times or Performance at 2 times. Vendors use the same names for different ratios.", ch: "9.3" },
    "quantization": { term: "Vertex quantization", aka: ["vertex compression","mesh compression","packing"], def: "Storing vertex attributes with fewer bits, for example 16-bit instead of 32-bit numbers, to save memory and bandwidth at a small loss of precision.", ch: "4.2" },
    "raci": { term: "RACI", aka: ["RACI matrix","RACI chart","responsibility assignment matrix"], def: "A grid of decisions or tasks against people that marks who is Responsible for doing the work, Accountable for the result, Consulted before and Informed after. Each row should have exactly one Accountable person.", ch: "1.2" },
    "radiance": { term: "Radiance", aka: ["L","outgoing radiance","incoming radiance"], def: "The light travelling along one direction, which is what a camera pixel or an eye measures. Luminance, measured in nits, is its everyday counterpart.", ch: "8.1" },
    "radiance-cascades": { term: "Radiance cascades", aka: ["radiance cascade"], def: "A GI method by Alexander Sannikov that stores light in a stack of probe grids: each level has probes twice as far apart, covers rays twice as long and resolves finer directions. Path of Exile 2 uses a screen-space version.", ch: "8.5" },
    "radiosity": { term: "Radiosity", aka: ["radiosity method"], def: "A way to compute bounced light between matte surfaces: cut them into patches, work out how much of each patch's light reaches every other, then pass light around until it settles.", ch: "8.1" },
    "rasterization": { term: "Rasterization", aka: ["rasterisation","scan conversion"], def: "The fixed GPU step that finds which pixels a triangle covers and gives each of them a blend of the values at the triangle's three corners.", ch: "5.3" },
    "rasterizer": { term: "Rasterizer", aka: ["rasterizer stage","raster stage"], def: "The fixed GPU stage that finds which pixels each triangle covers and hands each one to the pixel shader with values blended from the triangle's three corners.", ch: "5.1" },
    "ray": { term: "Ray", aka: ["rays","ray origin","ray direction","tMin","tMax"], def: "A starting point, a direction and a range of distances to search: the question of what is the first thing in that direction. Ray tracing answers it against the scene's geometry.", ch: "8.6" },
    "ray-budget": { term: "Ray budget", aka: ["rays per pixel","rpp","ray count"], def: "How many rays an effect may trace per pixel per frame. Real-time effects typically use a quarter of a ray to one ray per pixel and rely on denoising.", ch: "8.6" },
    "ray-coherence": { term: "Coherence", aka: ["coherent rays","ray coherence"], def: "How alike neighbouring rays are. Rays with similar origins and directions visit the same boxes and hit the same materials, so GPU lanes work together and data stays in the cache.", ch: "8.6" },
    "ray-divergence": { term: "Divergence", aka: ["divergent rays","incoherent rays","execution divergence"], def: "Neighbouring rays going different ways: they visit different parts of the tree and hit different materials, so lanes in one warp wait for each other and memory reads miss the cache.", ch: "8.6" },
    "ray-marching": { term: "Ray marching", aka: ["screen-space tracing"], def: "Following a ray in small steps and checking at each step whether it has gone behind a surface, often using the depth buffer.", ch: "8.4" },
    "ray-miss-fallback": { term: "Ray-miss fallback", aka: ["Ray Miss","fallback","fallback chain"], def: "What a screen-space effect uses for a ray that leaves the screen or finds nothing: a reflection or light probe, baked lighting, the sky, or a world-space GI method that can trace the whole scene.", ch: "8.4" },
    "ray-reconstruction": { term: "Ray reconstruction", aka: ["DLSS Ray Reconstruction","DLSS-RR","DLSS 3.5"], def: "NVIDIA's neural network, introduced with DLSS 3.5 in 2023, that replaces a game's hand-tuned denoisers for ray-traced lighting with one network trained on offline-rendered images.", ch: "8.7" },
    "ray-traced-reflections": { term: "Ray-traced reflections", aka: ["RT reflections","RTR"], def: "Reflections found by tracing the mirror direction, spread by roughness, against the real scene, so objects that are off screen or hidden still appear.", ch: "8.6" },
    "ray-traced-shadows": { term: "Ray-traced shadows", aka: ["RT shadows","Cast Ray Traced Shadows"], def: "Shadows found by tracing a ray from each pixel's surface towards the light and stopping at the first hit. Aiming at random points on an area light gives soft edges that widen with distance.", ch: "8.6" },
    "ray-tracing": { term: "Ray tracing", aka: ["RT","hardware ray tracing"], def: "Finding what a ray hits by testing it against the actual scene geometry, using acceleration structures that GPUs can now traverse in hardware.", ch: "8.6" },
    "ray-triangle-intersection": { term: "Ray-triangle intersection", aka: ["ray-triangle test","Möller–Trumbore","triangle test"], def: "The test of whether a ray passes through a triangle: find where it crosses the triangle's plane, then check that the point's three barycentric weights are all zero or more. It is the basic operation of ray tracing.", ch: "8.6" },
    "rayleigh-scattering": { term: "Rayleigh scattering", aka: ["Rayleigh"], def: "Scattering by particles much smaller than the wavelength of light, such as air molecules. It is far stronger for short wavelengths, which is why the clear sky is blue and the low sun is orange and red.", ch: "9.5" },
    "real-time-rendering": { term: "Real-time rendering", aka: ["real-time graphics","interactive rendering"], def: "Drawing images fast enough to keep up with the player, typically 30 to well over 100 images a second. Offline rendering for film can instead spend minutes or hours on a single image.", ch: "0.1" },
    "recommended-spec": { term: "Recommended specification", aka: ["recommended requirements","rec spec"], def: "The hardware a PC game suggests for the experience its makers intend, often given with a resolution, frame rate and settings preset.", ch: "1.4" },
    "reference-rendering": { term: "Reference rendering", aka: ["reference image","ground truth","converged image"], def: "An image rendered with enough samples to be correct, used to judge real-time approximations and tune them. Engine path tracers exist largely to make these.", ch: "8.7" },
    "reflection-fallback": { term: "Reflection fallback", aka: ["reflection hierarchy","fallback chain","reflection fallback order"], def: "The order in which reflection methods answer a pixel when the more accurate one has nothing, for example screen space, then a reflection probe, then the sky.", ch: "7.6" },
    "reflection-probe": { term: "Reflection probe", aka: ["reflection capture","ReflectionProbe","Sphere Reflection Capture","Box Reflection Capture","local light probe","cubemap probe"], def: "An environment map captured at a chosen point in a level and applied to surfaces within its area, so each area reflects its own surroundings. Usually baked in the editor; real-time ones re-render the scene.", ch: "7.6" },
    "reflex": { term: "NVIDIA Reflex", aka: ["Reflex","Reflex Low Latency","Reflex Low Latency mode"], def: "NVIDIA's latency reducer: it paces the CPU so frames do not queue up waiting for the GPU, cutting the time from input to screen. DLSS Frame Generation requires it.", ch: "9.3" },
    "refraction": { term: "Refraction", aka: ["screen-space refraction","distortion","refracted colour"], def: "Light bending as it passes from one material into another, as at a water or glass surface. Games fake it by reading a copy of the already drawn scene at an offset taken from the surface normal.", ch: "9.6" },
    "refresh-rate": { term: "Refresh rate", aka: ["Hz","hertz","refresh"], def: "How many times per second a display redraws its picture, in hertz (Hz). A 60 Hz display starts a new picture every 16.7 ms; a 144 Hz display every 6.9 ms.", ch: "3.1" },
    "register-pressure": { term: "Register pressure", aka: ["VGPR pressure","register usage","registers per thread"], def: "A shader needing many registers to hold its live values. Registers are shared by all the warps on a compute unit, so heavier shaders leave room for fewer warps and hide less memory latency.", ch: "11.2" },
    "render-pass": { term: "Render pass", aka: ["pass"], def: "One step in drawing a frame that reads some images and writes others, such as the shadow pass, the AO pass or the lighting pass.", ch: "5.6" },
    "render-pipeline": { term: "Render pipeline", aka: ["Scriptable Render Pipeline","SRP","rendering pipeline"], def: "The part of an engine that decides how each frame is drawn: which passes run, in what order and with which lighting. In Unity it is a swappable package, URP or HDRP.", ch: "2.4" },
    "render-state": { term: "Render state", aka: ["pipeline state","state change","GPU state","SetPass call"], def: "The settings the GPU needs in place before a draw: which shaders run, which buffers and textures are bound, and how blending, depth testing and face culling behave. Changing it between draws is a state change, which costs CPU time.", ch: "4.3" },
    "render-target": { term: "Render target", aka: ["RT","colour attachment","render texture","framebuffer attachment"], def: "An image the GPU draws into instead of, or before, the screen, such as a shadow map, a G-buffer layer or an HDR colour buffer. Later passes read it as a texture.", ch: "5.6" },
    "render-target-format": { term: "Render target format", aka: ["pixel format","colour buffer format","Color Buffer Format","HDR Precision"], def: "The pixel format of an image the GPU draws into, such as RGBA8 or R11G11B10F at 4 bytes per pixel or RGBA16F at 8. It sets the memory and bandwidth every pass that writes or reads the image costs.", ch: "11.2" },
    "render-thread": { term: "Render thread", aka: ["rendering thread","RenderThread"], def: "A CPU thread that takes a copy of what the game thread produced and turns it into work for the GPU, while the game thread is already updating the next frame.", ch: "2.2" },
    "renderer": { term: "Renderer", aka: ["rendering engine","render pipeline","rendering server"], def: "The part of an engine that turns the current state of the game world into an image each frame. It decides what is visible, organises the drawing into passes and sends the work to the GPU.", ch: "2.1" },
    "rendering-equation": { term: "Rendering equation", aka: ["light transport equation","Kajiya's equation"], def: "James Kajiya's 1986 equation for light leaving a point: what it emits, plus the light arriving from every direction times the material's response and the angle. Every lighting technique approximates it.", ch: "8.1" },
    "rendering-method": { term: "Rendering method", aka: ["Godot renderer","Mobile renderer","Compatibility renderer"], def: "Godot's choice of renderer for a project: Forward+ for desktop, Mobile for phones and standalone VR, or Compatibility for older hardware and the web.", ch: "2.4" },
    "rendering-path": { term: "Rendering path", aka: ["render path","rendering mode","lighting path"], def: "How a renderer organises the work of lighting a frame: forward, deferred, or either with tiled or clustered light lists. It sets how many lights a scene can afford and whether features such as MSAA are available.", ch: "7.3" },
    "reprojection": { term: "Reprojection", aka: ["history reprojection","reproject"], def: "Working out where each pixel's surface was on screen last frame, from motion vectors or from depth and the camera's movement, and reading the history from there.", ch: "9.2" },
    "resolution": { term: "Resolution", aka: ["output resolution","display resolution","1080p","1440p","4K"], def: "The number of pixels in an image, written width × height. 1920 × 1080 (1080p) is about 2.07 million pixels; 3840 × 2160 (4K) is four times as many.", ch: "3.1" },
    "resolution-scaling": { term: "Resolution scaling", aka: ["resolution test","resolution-sensitive","per-pixel cost"], def: "How a pass's cost changes with the number of pixels rendered. Per-pixel work costs four times as much at 4K as at 1080p, while shadow maps, vertex work and the CPU do not change.", ch: "11.2" },
    "restir": { term: "ReSTIR", aka: ["reservoir-based spatiotemporal importance resampling","ReSTIR DI","ReSTIR GI","ReSTIR PT","RTXDI"], def: "A 2020 technique that picks a good light sample for each pixel by resampling many cheap candidates, then shares the winners with neighbouring pixels and the next frame. It made scenes with millions of lights affordable at one shadow ray per pixel.", ch: "8.7" },
    "retopology": { term: "Retopology", aka: ["retopo","remeshing"], def: "Building a new, lighter mesh over a detailed sculpt, with edges placed where the shape and animation need them, so the model is cheap enough for a game.", ch: "1.3" },
    "reversed-z": { term: "Reversed-Z", aka: ["reverse Z","reversed depth","inverted depth buffer"], def: "Storing depth with the near plane at 1 and the far distance at 0, in a 32-bit floating-point depth buffer. It makes depth precision almost even across the view and greatly reduces z-fighting, at no cost.", ch: "5.5" },
    "rgb": { term: "RGB", aka: ["red, green, blue","RGB colour"], def: "Describing a colour as three amounts of light: red, green and blue. Every pixel on a screen mixes those three lights to make the colours it can show.", ch: "3.2" },
    "rhi": { term: "RHI", aka: ["render hardware interface","Rendering Hardware Interface","RenderingDevice","graphics abstraction layer"], def: "The layer that gives the renderer one set of graphics commands and translates them into whichever graphics API the platform uses, such as DirectX 12, Vulkan or Metal.", ch: "2.1" },
    "rhi-thread": { term: "RHI thread", aka: ["RHIT","RHIThread"], def: "In Unreal Engine, a third CPU thread that translates the render thread's platform-neutral command lists into DirectX 12, Vulkan or Metal calls and hands them to the GPU.", ch: "2.2" },
    "roughness": { term: "Roughness", aka: ["smoothness","glossiness","gloss"], def: "A material input from 0 (mirror-smooth) to 1 (fully matte) that sets how much a surface's microfacets disagree, and so how wide and dim its highlights are. Smoothness and glossiness are the same idea with the scale flipped.", ch: "6.5" },
    "royalty": { term: "Royalty", aka: ["revenue share"], def: "A percentage of a game's revenue paid to the engine maker. Unreal Engine charges one on a game's gross revenue above its first $1 million.", ch: "2.4" },
    "rt-cores": { term: "RT cores", aka: ["ray accelerators","ray tracing units","RT units","ray tracing hardware"], def: "GPU hardware that tests rays against boxes and triangles so shader cores do not have to. NVIDIA's RT cores also walk the BVH; AMD's ray accelerators test while shader code walks the tree.", ch: "8.6" },
    "rtao": { term: "RTAO", aka: ["ray-traced ambient occlusion"], def: "Ambient occlusion computed by tracing short rays against the real scene geometry instead of reading the depth buffer, so it sees hidden and off-screen objects.", ch: "8.3" },
    "rtgi": { term: "RTGI", aka: ["ray-traced global illumination","ray-traced GI"], def: "Bounced light gathered by tracing rays from surfaces or probes into the scene, usually with few rays per pixel and the results shared across neighbours and frames.", ch: "8.6" },
    "runtime": { term: "Runtime", aka: ["player","game build","shipping build"], def: "The part of an engine that ships inside the game and runs on players' machines. It contains the systems that run each frame, without the editor's tools.", ch: "2.1" },
    "sample-point": { term: "Sample point", aka: ["pixel centre","pixel center","sample location"], def: "The single point at which the GPU tests whether a triangle covers a pixel. Without multisampling it is the pixel's centre, half a pixel in from its top-left corner.", ch: "5.3" },
    "samples-per-pixel": { term: "Samples per pixel", aka: ["spp","SPP","paths per pixel","Samples Per Pixel","Maximum Samples"], def: "How many random paths or rays are averaged for each pixel. Noise falls with its square root: 4 times the samples give half the noise.", ch: "8.7" },
    "scalability": { term: "Scalability", aka: ["quality settings","quality levels","presets","scalability settings"], def: "The settings that let one game trade visual quality for speed and memory, grouped into presets for each platform and device tier.", ch: "1.4" },
    "scalability-group": { term: "Scalability group", aka: ["sg.ShadowQuality","sg.GlobalIlluminationQuality","quality group","Scalability Groups"], def: "One family of settings in Unreal's scalability system, such as shadows, global illumination, reflections or post-processing. Each has levels from Low to Epic and Cinematic, and each level sets many console variables at once.", ch: "10.3" },
    "scan-out": { term: "Scan-out", aka: ["scanout","raster scan"], def: "The display reading its picture out of the front buffer row by row, from the top of the screen to the bottom, during each refresh.", ch: "3.1" },
    "scene": { term: "Scene", aka: ["level","map","scene file",".umap",".unity",".tscn"], def: "One saved world or piece of a world, such as a level, a menu or a test room, holding every object placed in it. Unreal Engine calls it a level or map.", ch: "2.3" },
    "scene-graph": { term: "Scene graph", aka: ["scene hierarchy","hierarchy","scene tree","Outliner"], def: "The tree of every object in a scene, where each object can have children that move with it. Editors show it as the Hierarchy, the Outliner or the Scene dock.", ch: "2.3" },
    "scene-referred": { term: "Scene-referred", aka: ["scene referred","scene-linear values"], def: "Describing values as amounts of light in the scene, with no upper limit. Lighting, exposure and high-precision grading work on scene-referred values.", ch: "9.1" },
    "screen-edge-fade": { term: "Screen edge fade", aka: ["Screen Edge Fade Distance","edge fade","border fade"], def: "Blending screen-space hits away as they approach the edge of the frame, so a reflection or bounce fades out instead of popping when its source leaves the screen.", ch: "8.4" },
    "screen-probes": { term: "Screen probes", aka: ["Screen Probe Gather","screen space radiance cache","final gather"], def: "Lumen's final gather: probes placed on the visible surfaces, about one per 16 × 16 pixels, each gathering light from 64 directions. Their results are interpolated to every pixel, backed by a coarser world-space cache for distant light.", ch: "8.5" },
    "screen-size": { term: "Screen size", aka: ["screen coverage","% screen size","screen relative transition height","LOD threshold"], def: "How large an object appears on screen, usually its height as a fraction of the screen's height. Engines switch levels of detail when it crosses set thresholds, so a large object keeps its detail farther away than a small one.", ch: "4.5" },
    "screen-space": { term: "Screen space", aka: ["image space"], def: "Working from the rendered image and its depth rather than the 3D scene. Screen-space techniques are fast, but they only know about what the camera currently sees.", ch: "3.4" },
    "screen-space-derivatives": { term: "Screen-space derivatives", aka: ["derivatives","ddx","ddy","dFdx","dFdy","fwidth"], def: "How fast a value changes from one pixel to the next, measured by comparing neighbours in a 2 by 2 quad. Texture sampling uses them to pick the right mip level.", ch: "5.4" },
    "screen-tearing": { term: "Screen tearing", aka: ["tearing","tear line"], def: "A horizontal break across the picture where the rows above show one frame and the rows below show the next, because the frame was swapped while the display was still reading the screen out.", ch: "3.1" },
    "scripting-layer": { term: "Scripting layer", aka: ["scripting","gameplay scripting","Blueprints","GDScript","C# scripts"], def: "The language and interface gameplay programmers and designers use to write a game's logic on top of the engine, such as Blueprints, C# in Unity or GDScript in Godot.", ch: "2.1" },
    "sdfgi": { term: "SDFGI", aka: ["signed distance field global illumination"], def: "Godot's semi-real-time GI. It builds cascades of signed distance fields of static geometry around the camera, each cascade with cells twice the size of the one inside it, and lights them with probes; no baking, Forward+ only.", ch: "8.5" },
    "seamless-streaming": { term: "Seamless streaming", aka: ["open-world streaming","no loading screens","background streaming"], def: "Loading the world around the player in the background while they play, so there are no loading screens. It needs less memory at any moment, but loading must keep up with the player.", ch: "11.4" },
    "seat-licence": { term: "Seat licence", aka: ["per-seat subscription","seat"], def: "A licence paid for each person who uses the editor, usually yearly, whatever the game earns. Unity charges this way once a company passes its free tier.", ch: "2.4" },
    "self-time": { term: "Self time", aka: ["exclusive time","Self","self ms"], def: "The time a function spends in its own code, leaving out the functions it calls. Inclusive time adds them back, so ranking by self time finds the real cost instead of the containers around it.", ch: "11.3" },
    "shader": { term: "Shader", aka: ["shader program"], def: "A small program that runs on the GPU for every vertex, pixel or work item, in parallel.", ch: "5.1" },
    "shader-compilation": { term: "Shader compilation", aka: ["shader compile","shader compiling"], def: "Turning shader source into GPU machine code in two stages: into an in-between form such as DXIL or SPIR-V when the game is built, then into the player's exact GPU's code by the driver. The second stage causes hitches if it happens during play.", ch: "3.5" },
    "shader-complexity-view": { term: "Shader complexity view", aka: ["Shader Complexity","overdraw view","Display Overdraw"], def: "An engine debug view that colours each pixel by how much shading it costs, from cheap to expensive, so overlapping or heavy materials stand out.", ch: "5.4" },
    "shader-graph": { term: "Shader graph", aka: ["Material Editor","Shader Graph","Visual Shader","node-based shader editor"], def: "A node-based editor where artists build shaders by wiring boxes together. The engine turns the graph into ordinary shader code and compiles it like any other shader.", ch: "5.6" },
    "shader-stutter": { term: "Shader compilation stutter", aka: ["PSO stutter","shader hitch","compile hitch","first-use hitch"], def: "A hitch the first time something is drawn, because its pipeline state object is created and its shaders compiled by the driver at that moment instead of during loading.", ch: "5.6" },
    "shader-variant": { term: "Shader variant", aka: ["shader permutation","keyword variant","static switch"], def: "One compiled version of a shader for one combination of on/off features. Each independent toggle doubles the count, so five toggles make 32 variants before passes and platforms multiply them again.", ch: "5.6" },
    "shading-model": { term: "Shading model", aka: ["lighting model"], def: "The formula a renderer uses to turn the light arriving at a point, the surface's normal and material, and the direction of the camera into a colour. Engines offer a default lit model plus special ones for skin, cloth and hair.", ch: "7.2" },
    "shadow-acne": { term: "Shadow acne", aka: ["self-shadowing","erroneous self-shadowing","shadow moiré"], def: "Stripes or speckles of false shadow on lit surfaces, caused by a surface failing the shadow test against its own stored depth, because each texel stores one depth for a whole patch.", ch: "7.4" },
    "shadow-atlas": { term: "Shadow atlas", aka: ["shadow map atlas","Shadow Atlas Resolution","positional shadow atlas"], def: "One large texture holding the shadow maps of many lights in separate regions, usually with bigger regions for lights that are larger on screen.", ch: "7.5" },
    "shadow-bias": { term: "Shadow bias", aka: ["depth bias","constant bias","depth offset"], def: "A small offset that moves the shadow test towards the light so surfaces do not shadow themselves. Too little leaves shadow acne; too much detaches shadows from their casters.", ch: "7.4" },
    "shadow-caching": { term: "Shadow caching", aka: ["cached shadows","shadow update mode","On Demand shadows"], def: "Keeping a shadow map from earlier frames and rendering it again only when the light or something casting into it changes. It saves the whole shadow pass for things that stay still.", ch: "7.5" },
    "shadow-caster": { term: "Shadow caster", aka: ["caster","cast shadows","shadow-casting object"], def: "An object drawn into shadow maps, so it can block light. Whether an object casts shadows is a separate setting from whether it receives them.", ch: "7.4" },
    "shadow-distance": { term: "Shadow distance", aka: ["Max Distance","Dynamic Shadow Distance","shadow draw distance"], def: "How far from the camera real-time shadows reach. It sets the far end of the last cascade, so shortening it makes every cascade's texels smaller.", ch: "7.5" },
    "shadow-map": { term: "Shadow map", aka: ["shadow depth map","shadowmap"], def: "A depth image rendered from a light's point of view, storing for each texel the distance to the first surface the light meets. Any point further from the light than its texel's stored distance is in shadow.", ch: "7.4" },
    "shadow-pass": { term: "Shadow pass", aka: ["shadow depth pass","shadow map pass","shadow rendering"], def: "The render pass that draws every shadow caster into a light's shadow map, once per map or cube face. Its cost grows with the casters inside the light's view and the number of shadowed lights, not with screen resolution.", ch: "7.4" },
    "shadow-resolution": { term: "Shadow map resolution", aka: ["shadow resolution","shadow texel density","shadow map size"], def: "How many texels a shadow map has, and so how much of the world each texel covers. No shadow edge can be sharper than one texel.", ch: "7.4" },
    "shadow-test": { term: "Shadow test", aka: ["shadow comparison","shadow lookup"], def: "Projecting a pixel's position into the shadow map and comparing its light-space depth with the stored depth: if the pixel is further from the light, something blocks it and it is in shadow.", ch: "7.4" },
    "shadowmask": { term: "Shadow mask", aka: ["Shadowmask","Distance Shadowmask","distance field shadow map","shadowmask_mode"], def: "A baked texture that stores how much each texel is shadowed from a particular light, so the light's direct lighting can be computed every frame while its shadows from static objects stay baked.", ch: "8.2" },
    "sharpening": { term: "Sharpening", aka: ["sharpen filter","Contrast Adaptive Sharpening","CAS","RCAS","Post Sharpen","unsharp mask"], def: "A filter that steepens edges by pushing each side away from the other, used after TAA and upscalers to restore crispness. Too much draws bright and dark outlines, called ringing.", ch: "9.2" },
    "signed-distance-field": { term: "Signed distance field", aka: ["SDF","distance field","mesh distance field","Global Distance Field"], def: "A volume storing, at each point, the distance to the nearest surface: positive outside, negative inside. A ray can safely jump that far at every step, which makes tracing fast.", ch: "7.5" },
    "significance": { term: "Significance", aka: ["Significance Manager","logic LOD","update LOD","tick LOD","update rate optimisation"], def: "A score for how much an object matters to the player right now, from its distance, visibility or role. Games use it to update less significant objects less often or more cheaply, like level of detail for logic.", ch: "11.3" },
    "simd": { term: "SIMD and SIMT", aka: ["SIMD","SIMT","single instruction, multiple data","single instruction, multiple threads"], def: "Running many lanes from one stream of instructions: the hardware issues each instruction once and every lane in a group applies it to its own data. SIMT is NVIDIA's name for the version where each lane looks like its own thread.", ch: "3.5" },
    "skeleton": { term: "Skeleton", aka: ["rig","armature","Skeleton3D","Skeleton asset"], def: "A hierarchy of bones that animation poses every frame and that a skinned mesh follows. Each bone is placed relative to its parent, so moving a shoulder carries the arm and hand with it.", ch: "4.6" },
    "skin-weights": { term: "Skin weights", aka: ["bone weights","vertex weights","weight painting","influences"], def: "Numbers stored per vertex saying how strongly each of a few bones moves it. They add up to 1 and are painted by riggers.", ch: "4.6" },
    "skinned-mesh": { term: "Skinned mesh", aka: ["Skeletal Mesh","Skinned Mesh Renderer","skinned model"], def: "A mesh whose vertices also store bone numbers and skin weights, so that it can follow a skeleton.", ch: "4.6" },
    "skinning": { term: "Skinning", aka: ["skeletal deformation","vertex skinning","mesh deformation"], def: "Moving every vertex of a mesh each frame to follow the bones of its skeleton, according to each vertex's skin weights.", ch: "4.6" },
    "sky-atmosphere": { term: "Sky atmosphere model", aka: ["physically based sky","Sky Atmosphere","Physically Based Sky","PhysicalSkyMaterial","atmospheric scattering"], def: "A renderer's simulation of light scattering through a planet's atmosphere from its Rayleigh, Mie and absorption settings. It gives the sky's colour for any sun angle and the haze over distant terrain, usually through small lookup tables rebuilt every frame.", ch: "9.5" },
    "sky-light": { term: "Sky light", aka: ["ambient light","environment light"], def: "Light arriving from the whole surrounding environment rather than one point, such as the blue sky on a sunny day or a uniform grey overcast.", ch: "7.1" },
    "slice": { term: "Slice", aka: ["slice direction"], def: "In GTAO, one direction across the screen through a pixel. The pixel's hemisphere is examined one thin vertical slice at a time.", ch: "8.3" },
    "slope-scaled-bias": { term: "Slope-scaled bias", aka: ["slope bias","slope-scale depth bias","SlopeScaledDepthBias"], def: "Shadow bias that grows with how steeply a surface is tilted against the light, where one texel spans the largest change in depth. It gives each surface roughly the bias it needs.", ch: "7.4" },
    "smaa": { term: "SMAA", aka: ["Subpixel Morphological Anti-Aliasing","Enhanced Subpixel Morphological Antialiasing","SMAA 1x","SMAA T2x"], def: "Post-process anti-aliasing by Jorge Jimenez and colleagues (2012) that reads the shape of stair-step patterns in three passes and blends each pixel by the area under the rebuilt edge. Sharper than FXAA.", ch: "9.2" },
    "small-object-culling": { term: "Small-object culling", aka: ["screen-size culling","contribution culling","screen size culling"], def: "Skipping objects whose projected size on screen falls below a threshold, such as a few pixels, because they would barely change the image.", ch: "4.4" },
    "small-triangle-cost": { term: "Small-triangle cost", aka: ["micro-triangles","micropolygons","tiny triangles"], def: "The extra GPU work caused by triangles only a few pixels in size: each still needs setup and shades whole 2 by 2 pixel quads, so up to three quarters of the shading is thrown away.", ch: "5.3" },
    "soft-particles": { term: "Soft particles", aka: ["depth fade","DepthFade","Proximity Fade","Soft Particles"], def: "Fading a particle where it comes close to the surface behind it, using the difference between its depth and the depth buffer, so flat sprites do not cut a hard line where they cross walls and floors.", ch: "9.6" },
    "software-ray-tracing": { term: "Software ray tracing", aka: ["Lumen Software Ray Tracing","SWRT","distance field tracing","Global Tracing","Detail Tracing"], def: "Lumen's tracing mode that marches rays through signed distance fields of the scene instead of its triangles. It runs on any Shader Model 6 GPU without ray-tracing hardware, at lower quality than hardware ray tracing.", ch: "10.3" },
    "source-asset": { term: "Source asset", aka: ["source file","source art","working file"], def: "The editable original of a piece of content, such as a sculpt or a layered texture project. The team keeps and versions it; players never receive it.", ch: "1.3" },
    "source-available": { term: "Source-available", aka: ["source access","engine source"], def: "Source code you may read and change under the vendor's licence, but not share or reuse freely. Unreal Engine's full source is available this way.", ch: "2.4" },
    "sparse-texture": { term: "Sparse texture", aka: ["tiled resources","sparse residency","reserved resources","partially resident texture"], def: "A texture with only some of its memory pages backed by real memory, using the GPU's own memory mapping. It is the hardware support behind some virtual texturing systems.", ch: "6.3" },
    "spatial-upscaling": { term: "Spatial upscaling", aka: ["spatial upscaler","FSR 1","bilinear upscale","Catmull-Rom upscale","MetalFX Spatial"], def: "Enlarging one rendered frame to the display resolution by interpolating between its pixels, sometimes with edge-aware sharpening. Cheap, and it cannot restore detail the frame never sampled.", ch: "9.3" },
    "specular": { term: "Specular reflection", aka: ["specular","highlights"], def: "Light reflected in a preferred direction, like a mirror or a highlight on polished metal. It changes as the viewer moves.", ch: "7.2" },
    "specular-aliasing": { term: "Specular aliasing", aka: ["specular shimmer","shading aliasing","sparkling highlights"], def: "Flickering bright pixels on shiny, bumpy or finely curved surfaces, where highlights smaller than a pixel are caught by some pixels' single sample and missed by others.", ch: "9.2" },
    "specular-gi": { term: "Specular GI", aka: ["indirect specular","specular global illumination","reflections"], def: "Bounced light seen in reflections, such as a red wall mirrored in a shiny floor. It changes with every camera move and is handled by reflection techniques.", ch: "8.1" },
    "specular-glossiness": { term: "Specular/glossiness workflow", aka: ["spec/gloss","specular workflow","Specular Color"], def: "An older way to author PBR materials, with diffuse, specular colour and glossiness maps. It gives direct control over F0 but makes physically impossible values easy to enter.", ch: "6.5" },
    "specular-highlight": { term: "Specular highlight", aka: ["specular blob","hotspot"], def: "The bright spot where a surface reflects a light source towards the camera, in effect a blurred image of the light. Its size shows how rough the surface is, and it slides across the surface as the viewer moves.", ch: "7.2" },
    "specular-occlusion": { term: "Specular occlusion", aka: ["GTSO","ground-truth specular occlusion"], def: "Darkening reflections in creases and cavities where the reflected direction is blocked by nearby geometry.", ch: "8.3" },
    "spherical-harmonics": { term: "Spherical harmonics", aka: ["SH","L2 SH","SH coefficients","SH bands","third order SH"], def: "A way to describe a quantity that varies smoothly with direction, such as the light arriving at a probe, as a short list of numbers. Nine numbers per colour channel, three bands, hold soft lighting from all directions closely enough for matte surfaces.", ch: "8.2" },
    "spir-v": { term: "SPIR-V", aka: ["SPIRV"], def: "A standard intermediate format for compiled shaders, defined by the Khronos Group. Vulkan drivers read it, and tools translate between it and HLSL, GLSL and Metal's language.", ch: "5.6" },
    "splat-map": { term: "Splat map", aka: ["splatmap","weightmap","weight map","control texture","Landscape Layer Blend"], def: "A texture whose channels hold the weight of each terrain material layer at each point, so grass, rock, sand and snow can be painted and blended. One RGBA texture covers four layers.", ch: "9.6" },
    "split-sum": { term: "Split-sum approximation", aka: ["split sum","environment BRDF","DFG LUT","BRDF integration map"], def: "Brian Karis's way of making image-based specular lighting cheap: a prefiltered environment map multiplied by a small precomputed table that gives a scale and bias for the material's reflectance, by roughness and viewing angle.", ch: "7.6" },
    "split-vertex": { term: "Split vertex", aka: ["seam","hard edge","duplicated vertex"], def: "A corner stored as two or more vertices at the same position because the triangles meeting there need different normals, UVs or colours.", ch: "4.2" },
    "spot-light": { term: "Spot light", aka: ["spotlight","Spot Light","SpotLight3D","cone light"], def: "A point light limited to a cone, like a torch. It is at full strength inside the inner cone angle and fades to nothing at the outer cone angle.", ch: "7.1" },
    "srgb": { term: "sRGB", aka: ["sRGB transfer function","sRGB gamut","Rec. 709 primaries","IEC 61966-2-1"], def: "The standard colour space for PC screens and the web. It fixes which red, green and blue the screen uses, and a curve that stores values so that 8 bits are spent where eyes notice differences.", ch: "3.2" },
    "srp-batcher": { term: "SRP Batcher", aka: ["Scriptable Render Pipeline Batcher"], def: "Unity's draw call optimisation for URP and HDRP. It keeps material data in GPU memory, so consecutive draws using the same shader variant need almost no set-up; the number of draws stays the same.", ch: "4.3" },
    "ssaa": { term: "SSAA", aka: ["supersampling","supersample anti-aliasing","downsampling","resolution scale above 100%"], def: "Supersample anti-aliasing: rendering and shading the frame at a higher resolution, then averaging it down. It removes every kind of aliasing, at a cost that grows with the number of samples.", ch: "9.2" },
    "ssao": { term: "SSAO", aka: ["screen-space ambient occlusion"], def: "Ambient occlusion estimated from the depth buffer by testing a handful of nearby sample points per pixel. Fast, noisy, and limited to what is on screen.", ch: "8.3" },
    "ssgi": { term: "SSGI", aka: ["screen-space global illumination","SSIL","screen-space indirect lighting"], def: "Bounced light estimated by tracing rays through the depth buffer and picking up colour from the lit image. It inherits every screen-space blind spot.", ch: "8.4" },
    "ssr": { term: "SSR", aka: ["screen-space reflections"], def: "Reflections found by tracing rays through the depth buffer and reusing the colour of whatever on-screen pixel they hit.", ch: "7.6" },
    "static-batching": { term: "Static batching", aka: ["Batching Static"], def: "Combining meshes that never move and share a material into large world-space buffers ahead of time, so they draw with fewer draw calls. It stores a copy of the mesh for every placement and culls less precisely.", ch: "4.3" },
    "static-buffer": { term: "Static buffer", aka: ["static vertex buffer","immutable buffer"], def: "A GPU buffer filled once, usually at load time, and then only read. Most level geometry and props use static buffers.", ch: "4.2" },
    "static-light": { term: "Static light", aka: ["baked light","Static","Baked"], def: "A light whose effect is computed before the game runs and stored, usually in lightmaps. It costs almost nothing at runtime but cannot move or change.", ch: "7.1" },
    "stencil-buffer": { term: "Stencil buffer", aka: ["stencil","custom stencil"], def: "A screen-sized buffer holding a small whole number per pixel, usually 8 bits, stored alongside depth. Draws write marks into it and later draws test against them, for outlines, portals and masks.", ch: "5.5" },
    "stencil-test": { term: "Stencil test", aka: ["stencil compare"], def: "The per-pixel comparison between a draw's reference value and the number stored in the stencil buffer, with rules for how the stored number changes when the test passes or fails.", ch: "5.5" },
    "store-action": { term: "Store action", aka: ["store op","storeOp","VK_ATTACHMENT_STORE_OP","MTLStoreAction","Store, Don't care"], def: "What a render pass does with an image when it ends: store it to memory for later passes, or discard it (Don't care). Discarding depth and MSAA samples that nothing reads again saves a full-screen write.", ch: "10.2" },
    "stp": { term: "STP", aka: ["Spatial-Temporal Post-processing","Spatial-Temporal Post-Processing (STP) 1.0"], def: "Unity 6's built-in software temporal upscaler for URP and HDRP. It needs compute shaders, does not run on OpenGL ES, and turns TAA on.", ch: "9.3" },
    "streaming-pool": { term: "Texture streaming pool", aka: ["texture pool","streaming pool","pool size","r.Streaming.PoolSize"], def: "The fixed amount of GPU memory a texture streamer may fill. When the mips the camera wants do not fit, it drops the sharpest levels, so textures look soft.", ch: "6.3" },
    "streaming-starvation": { term: "Streaming starvation", aka: ["texture starvation","pop-in","late streaming","blurry textures"], def: "A streaming system that cannot get the memory or read speed it needs, so textures stay blurry, meshes stay at low detail and objects appear late.", ch: "11.4" },
    "stride": { term: "Stride", aka: ["vertex size"], def: "The number of bytes from the start of one vertex to the start of the next in a buffer. It is the size of one row.", ch: "4.2" },
    "struct-of-arrays": { term: "Struct of arrays", aka: ["structure of arrays","data-oriented layout"], def: "Storing each field of many objects in its own packed array, such as all positions together, instead of one record per object. Loops that read one field then use every byte of each cache line they fetch.", ch: "11.3" },
    "subpass": { term: "Subpass", aka: ["Vulkan subpass","merged subpasses","input attachment","multipass","native render pass"], def: "A step inside one Vulkan render pass that can read the previous step's output at the same pixel as an input attachment. When the driver merges subpasses, the in-between images never leave tile memory.", ch: "10.2" },
    "subpixel-jitter": { term: "Subpixel jitter", aka: ["jitter","camera jitter","projection jitter","jitter offset","Jitter Scale"], def: "A tiny offset, less than a pixel, added to the camera's projection each frame so that every frame samples slightly different points. Temporal anti-aliasing and upscaling build their extra samples from it.", ch: "9.2" },
    "subsurface-scattering": { term: "Subsurface scattering", aka: ["SSS","screen-space subsurface scattering","Subsurface Profile","Diffusion Profile","separable SSS"], def: "Light entering a surface, wandering inside and leaving at a different point, as in skin, wax, marble and leaves. Games usually blur each pixel's diffuse light across the screen by a per-material profile, widest for red.", ch: "9.6" },
    "surface-cache": { term: "Surface cache", aka: ["Lumen surface cache","Lumen cards","cards","Lumen Scene"], def: "Lumen's store of material and lighting for the surfaces around the camera, captured onto small rectangles called cards placed around each mesh. Rays that hit the scene read their light from it instead of shading the hit.", ch: "8.5" },
    "sustained-performance": { term: "Sustained performance", aka: ["sustainable performance","sustained frame rate","steady-state performance"], def: "The level of work a device can keep up for a whole play session without overheating, below what it reaches in the first few minutes. Mobile budgets are set against it, not against the peak.", ch: "10.2" },
    "svgf": { term: "SVGF", aka: ["spatiotemporal variance-guided filtering","variance-guided filtering"], def: "A 2017 denoiser for one-sample-per-pixel path tracing: it accumulates each pixel's history, estimates how noisy each pixel is, and blurs more where noise is high, stopping at depth and normal edges.", ch: "8.7" },
    "swap-chain": { term: "Swap chain", aka: ["swapchain","flip chain"], def: "The set of framebuffers, usually two or three, that the graphics API passes in turn between the GPU and the display, together with the rules for when they swap.", ch: "3.1" },
    "taa": { term: "TAA", aka: ["temporal anti-aliasing"], def: "Anti-aliasing that jitters the camera slightly every frame and blends each new frame with the reprojected previous ones.", ch: "9.2" },
    "taa-blur": { term: "TAA blur", aka: ["temporal blur","TAA softness","reprojection blur"], def: "The softness temporal anti-aliasing adds: history is resampled every frame and filtered over more than a pixel, so fine detail spreads, especially in motion.", ch: "9.2" },
    "tangent": { term: "Tangent", aka: ["tangent vector","tangent frame"], def: "A direction lying along a surface, aligned with its texture's horizontal axis. Normal maps need it to know which way is which.", ch: "4.1" },
    "tangent-space": { term: "Tangent space", aka: ["TBN","tangent basis","texture space"], def: "A frame of reference sitting on the surface at each point, made of the normal, the tangent and the bitangent. Normal maps are usually written in it, so they work on any shape, tile and bend with animation.", ch: "6.4" },
    "technical-artist": { term: "Technical artist", aka: ["TA","tech artist"], def: "A specialist who works between art and programming. Technical artists build materials, shaders, tools and import rules, and make sure art looks right in the engine and stays within its performance budgets.", ch: "1.2" },
    "temporal-accumulation": { term: "Temporal accumulation", aka: ["history","temporal filter","temporal reprojection"], def: "Spreading work over several frames: each frame computes a few new samples and blends them with the result from previous frames, moved to account for motion.", ch: "9.2" },
    "temporal-upscaling": { term: "Temporal upscaling", aka: ["temporal upscaler","super resolution","TAAU","TAA Upscale","MetalFX Temporal"], def: "Rendering fewer pixels with a jittered camera and accumulating the samples of several frames into a full-resolution history, so the output holds more real detail than any one frame. TAA and upscaling in one pass.", ch: "9.3" },
    "terrain": { term: "Terrain", aka: ["heightmap terrain","Landscape","Terrain (Unity)","heightfield"], def: "Ground built from a height map: a grid of vertices raised by the map's values, split into sections so distant parts use fewer triangles, and painted with blended material layers.", ch: "9.6" },
    "tessellation": { term: "Tessellation", aka: ["hardware tessellation","hull and domain shaders","tessellation shaders"], def: "Splitting triangles into many smaller ones on the GPU at draw time, often to add displaced detail up close. Direct3D 11 added hardware stages for it; Unreal Engine 5 removed them in favour of Nanite.", ch: "4.5" },
    "texel": { term: "Texel", aka: ["texture element","texture pixel"], def: "One value in a texture's grid, the texture's equivalent of a pixel. Texels rarely line up one to one with screen pixels, so the GPU filters between them.", ch: "6.1" },
    "texel-density": { term: "Texel density", aka: ["texels per metre","px/m","pixels per metre"], def: "How many texels cover each metre of a surface: the texels across a UV island divided by the metres across its face. Assets seen together need a shared target, or some look blurrier than others.", ch: "6.1" },
    "texture": { term: "Texture", aka: ["map"], def: "An image the GPU reads while shading, such as a colour, normal or roughness map. Also used to store data like depth or AO.", ch: "6.1" },
    "texture-aliasing": { term: "Texture aliasing", aka: ["shimmer","moiré","sparkle","crawling"], def: "Noise, false patterns and flicker that appear when one pixel covers many texels but reads only a few of them. Mipmaps are the standard cure.", ch: "6.2" },
    "texture-array": { term: "Texture array", aka: ["2D array texture","Texture2DArray","array texture"], def: "A stack of textures of the same size and format, read with UV coordinates plus a layer number that the shader can choose for each pixel.", ch: "6.1" },
    "texture-atlas": { term: "Texture atlas", aka: ["atlas","sprite sheet"], def: "One texture holding the images of several objects in separate regions, so they can share one texture and one material. Regions cannot tile and need gaps between them.", ch: "6.1" },
    "texture-bound": { term: "Texture-bound", aka: ["texture-fetch-bound","sampler-bound","TEX-bound"], def: "A GPU pass limited by the texture units that fetch and filter texels, as in blurs and screen-space effects that take many samples. Fewer or cheaper samples make it faster.", ch: "11.2" },
    "texture-budget": { term: "Texture memory budget", aka: ["texture budget","Memory Budget","VRAM budget"], def: "The share of the weakest target's memory that a game's textures may use, after render targets, geometry and everything else. Texture sizes, formats and streaming are tuned to fit it.", ch: "6.3" },
    "texture-filtering": { term: "Texture filtering", aka: ["filtering","filter mode","sampler filter"], def: "How the GPU turns the texels around a sample point into one value when texels and pixels are different sizes. The usual modes are nearest, bilinear, trilinear and anisotropic.", ch: "6.2" },
    "texture-resolution": { term: "Texture resolution", aka: ["texture size","texture dimensions","max size"], def: "A texture's width and height in texels, such as 2048 × 2048. Memory grows with the square of the side, so doubling it costs four times as much.", ch: "6.1" },
    "texture-streaming": { term: "Texture streaming", aka: ["texture streamer","streaming"], def: "Loading and unloading parts of textures while the game runs, so memory holds only the detail the camera currently needs and the rest stays on disk.", ch: "6.3" },
    "thermal-headroom": { term: "Thermal headroom", aka: ["getThermalHeadroom","thermal state","ProcessInfo.thermalState","thermal status"], def: "How close a device is to throttling, as reported to the game: Android gives a forecast from 0 to 1, where 1 means severe throttling, and iOS a state from nominal to critical. Games use it to lower quality before the device slows them down.", ch: "10.2" },
    "thermal-throttling": { term: "Thermal throttling", aka: ["throttling","thermal limiting"], def: "A device lowering its chips' clock speeds when it gets too hot, which makes a game slow down partway through a session.", ch: "1.4" },
    "thickness-heuristic": { term: "Thickness heuristic", aka: ["thickness"], def: "A guess that surfaces in the depth buffer are only so thick, so geometry behind them is treated as open. It reduces dark halos around thin foreground objects.", ch: "8.3" },
    "thread-group": { term: "Thread group", aka: ["workgroup","work group","numthreads","dispatch"], def: "A block of compute shader threads, such as 8 × 8, that run together on one compute unit and can share fast memory. A dispatch launches a grid of thread groups.", ch: "5.6" },
    "tick": { term: "Update", aka: ["tick","Tick()","Update()","_process()"], def: "The step in each frame where the engine moves the game forward by the time that has passed: it reads input, runs gameplay code and updates every object that needs it.", ch: "2.2" },
    "tile-based-gpu": { term: "Tile-based GPU", aka: ["tile-based rendering","TBR","tile-based deferred rendering","TBDR","tiler"], def: "A GPU that sorts a pass's triangles into small screen tiles, then renders each tile in fast on-chip memory and writes it out once. Phone GPUs work this way to save memory traffic, power and heat.", ch: "3.5" },
    "tile-memory": { term: "Tile memory", aka: ["on-chip tile memory","tile buffer","GMEM","imageblock memory","local tile memory"], def: "The small, fast memory inside a tile-based GPU that holds one tile's colour, depth and samples while it is drawn. Reading and writing it costs far less time and energy than main memory.", ch: "10.2" },
    "tiled-shading": { term: "Tiled shading", aka: ["tiled deferred","tiled forward","tiled lighting","FPTL"], def: "Light culling that cuts the screen into small tiles, such as 32 × 32 pixels, and lists the lights reaching each tile, so each pixel loops over a short list instead of every light.", ch: "7.3" },
    "time-slicing": { term: "Time-slicing", aka: ["amortising","staggered updates","frame budgeting","time limit per frame"], def: "Spreading periodic or large work over several frames under a per-frame limit, such as updating a quarter of the characters each frame, so no frame pays for all of it.", ch: "11.3" },
    "tlas": { term: "TLAS", aka: ["top-level acceleration structure","top-level AS","instance acceleration structure"], def: "The acceleration structure over a scene's instances: each entry points at a BLAS and stores the instance's transform, ID and mask. Engines rebuild it every frame.", ch: "8.6" },
    "tone-curve": { term: "Tone curve", aka: ["tone mapping curve","toe","shoulder","S-curve"], def: "The function a tone mapper applies: a dark toe, a nearly straight middle and a shoulder that rolls highlights off towards white instead of clipping them.", ch: "9.1" },
    "tone-mapping": { term: "Tone mapping", aka: ["tonemapping","tone mapper","tonemapper","view transform","display transform"], def: "Turning the frame's scene light, which can be thousands of times brighter than white, into values a screen can show, with a curve that keeps highlights and shadows readable instead of clipping them.", ch: "9.1" },
    "tools-programmer": { term: "Tools programmer", aka: ["tools engineer","pipeline programmer"], def: "A programmer who builds the editors, importers, build systems and automation that the rest of the team uses to make the game.", ch: "1.2" },
    "toon-shading": { term: "Toon shading", aka: ["cel shading","cel-shading","anime shading"], def: "A stylised shading model that cuts smooth lighting into a few flat bands, usually with hard-edged highlights and ink outlines, so 3D models look like hand-drawn animation.", ch: "7.2" },
    "topology": { term: "Topology", aka: ["mesh topology","edge flow","edge loops"], def: "How a mesh's corners, edges and faces connect to each other, whatever their exact positions. Clean topology is easy to edit, unwrap and reduce, and deforms well when animated.", ch: "4.1" },
    "transform": { term: "Transform", aka: ["position, rotation and scale","TRS"], def: "An object's position, rotation and scale. Every object placed in a game world has one.", ch: "2.3" },
    "transform-hierarchy": { term: "Transform hierarchy", aka: ["parent-child","parenting","attachment"], def: "Parent and child links between objects, so that moving, turning or scaling a parent does the same to all of its children.", ch: "2.3" },
    "transmission": { term: "Transmission", aka: ["thin-surface translucency","thin translucency","backlight","Two Sided Foliage"], def: "Light passing right through a thin part of a surface, such as a leaf, an ear or a curtain, and lighting its far side. Shaders estimate it from the surface's thickness and the light behind it.", ch: "9.6" },
    "transparency-sorting": { term: "Transparency sorting", aka: ["sort order","translucency sort","back-to-front sorting","sort priority"], def: "Drawing transparent objects after all opaque ones, ordered from the furthest to the nearest, usually by the distance to each object's centre. It fails for large or intersecting transparent objects.", ch: "5.5" },
    "transparents-pass": { term: "Transparents pass", aka: ["transparent pass","translucency pass","Translucency","forward transparent pass"], def: "The part of a frame that draws see-through surfaces such as glass, water and particles after the opaque scene is lit, sorted back to front and lit as they are drawn, usually without writing depth.", ch: "10.1" },
    "traversal-stutter": { term: "Traversal stutter", aka: ["streaming stutter","streaming hitch","cell activation hitch"], def: "Hitches that appear as the player moves through a streamed world, usually when a newly loaded area is made live on the game thread all at once. They get worse the faster the player travels.", ch: "11.4" },
    "triangle": { term: "Triangle", aka: ["polygon","face","primitive"], def: "The basic shape GPUs draw. Three corners always lie on one flat plane, which makes triangles fast and unambiguous to fill.", ch: "4.1" },
    "triangle-list": { term: "Triangle list", aka: ["primitive topology"], def: "The most common way to read indices: every three indices form one independent triangle.", ch: "4.2" },
    "triangulation": { term: "Triangulation", aka: ["triangulate","triangulated"], def: "Splitting quads and n-gons into triangles, on export, on import or in the engine. Doing it once, at a known point, keeps the triangles identical in every tool.", ch: "4.1" },
    "trilinear-filtering": { term: "Trilinear filtering", aka: ["trilinear","linear mipmap filtering","Tri-linear"], def: "Bilinear filtering in the two nearest mip levels, blended by where the pixel's size falls between them. It hides the lines where one mip level hands over to the next.", ch: "6.2" },
    "trim-sheet": { term: "Trim sheet", aka: ["trim texture","trims"], def: "A texture made of horizontal strips of reusable detail, such as edges, seams and pipes, that tile along U. Many meshes lay their UVs over the strips and share it at one texel density.", ch: "6.1" },
    "triple-buffering": { term: "Triple buffering", aka: ["three-buffer swap chain"], def: "Using three framebuffers so the GPU can start the next frame while a finished one waits for the display. It keeps the GPU busy under vsync at the cost of up to one more frame of delay.", ch: "3.1" },
    "tsr": { term: "TSR", aka: ["Temporal Super Resolution","r.AntiAliasingMethod 4"], def: "Unreal Engine 5's built-in temporal upscaler and anti-aliasing, on by default. It runs on any Shader Model 5 GPU and on current consoles, with scalability settings for its cost.", ch: "9.3" },
    "ubershader": { term: "Ubershader", aka: ["uber shader","mega shader"], def: "One large shader that handles many features with branches instead of separate compiled variants. It needs fewer compiles but usually runs slower than a specialised variant.", ch: "5.6" },
    "ui-compositing": { term: "UI compositing", aka: ["UI pass","HUD pass","interface pass","UI overlay"], def: "Drawing the game's interface over the finished 3D image as the last step before present, at the display's own resolution and after every camera effect, so text stays sharp.", ch: "10.1" },
    "uncompressed-format": { term: "Uncompressed format", aka: ["RGBA8","RGBA32","R8G8B8A8","RGBA16F"], def: "A texture format that stores every texel in full, such as RGBA8 at 4 bytes per texel. Exact, but four to eight times larger than block-compressed formats.", ch: "6.3" },
    "unified-memory": { term: "Unified memory", aka: ["shared memory","UMA"], def: "One pool of memory shared by the CPU and GPU, as on consoles, phones and headsets, instead of separate system RAM and VRAM as on most PCs.", ch: "1.4" },
    "unit-throughput": { term: "Unit throughput", aka: ["SOL%","speed of light","peak-performance percentage","throughput %"], def: "How busy one GPU unit was during a pass, as a percentage of the most it could do. The unit with the highest reading is the likely limit: above about 80% it needs less work, and below about 60% the units are mostly waiting.", ch: "11.2" },
    "unit-vector": { term: "Unit vector", aka: ["normalised vector","normalized vector","normalise","normalize","direction"], def: "A vector with a length of exactly 1, so it carries only a direction. Normalising a vector divides it by its own length to make it one.", ch: "3.3" },
    "unity": { term: "Unity", aka: ["Unity 6","Unity engine"], def: "Unity Technologies' engine, scripted in C#, with two current render pipelines, URP and HDRP. It is licensed per seat and free for small companies.", ch: "2.4" },
    "unreal-engine": { term: "Unreal Engine", aka: ["UE5","UE","Unreal"], def: "Epic Games' engine, written in C++ with Blueprint visual scripting. Its fifth version brought features such as Nanite geometry and Lumen lighting, and it charges games a royalty on revenue above $1 million.", ch: "2.4" },
    "up-axis": { term: "Up axis", aka: ["Y-up","Z-up","vertical axis"], def: "The axis a coordinate system treats as vertical. Unity, Godot and glTF use Y; Unreal Engine, Blender and 3ds Max use Z.", ch: "3.4" },
    "urp": { term: "URP", aka: ["Universal Render Pipeline"], def: "Unity's render pipeline for every platform Unity supports, tuned for mobile GPUs and standalone VR. Unity recommends it for new projects.", ch: "2.4" },
    "usd": { term: "USD", aka: ["OpenUSD","Universal Scene Description",".usda",".usdc",".usdz"], def: "Pixar's open-source scene description format, built for assembling large scenes from many files. Layers, references and variants let teams change a scene without editing the original files.", ch: "1.3" },
    "uv": { term: "UV coordinates", aka: ["UVs","texture coordinates","texcoords"], def: "Two numbers per vertex saying which point of a 2D texture lands on that corner of the 3D surface.", ch: "4.1" },
    "uv-island": { term: "UV island", aka: ["UV shell","UV chart","island"], def: "One connected flat piece of a mesh's UV layout, bounded by seams. Islands are packed into the texture with gaps between them.", ch: "6.1" },
    "uv-seam": { term: "UV seam", aka: ["seam","texture seam","UV cut"], def: "An edge where the UV layout is cut so the surface can lie flat in the texture. The triangles on either side land in different places in the texture, so vertices along the seam are stored twice.", ch: "4.1" },
    "uv-unwrap": { term: "UV unwrapping", aka: ["unwrap","UV mapping","UV layout"], def: "Giving each vertex of a mesh its UV coordinates by cutting the surface along seams, flattening the pieces and packing them into the texture's 0 to 1 square.", ch: "6.1" },
    "variable-hardware": { term: "Variable hardware", aka: ["open platform","hardware fragmentation"], def: "A platform where players own very different machines, such as PCs and Android phones, so a game must adapt its settings to each one.", ch: "1.4" },
    "vector": { term: "Vector", aka: ["direction vector","displacement","float3","Vector3","FVector"], def: "An arrow written as a list of numbers, one per axis: (3, 2) means 3 along x and 2 along y. It has a direction and a length but no fixed place, so games use it for movement, velocity and facing.", ch: "3.3" },
    "version-control": { term: "Version control", aka: ["source control","revision control","VCS"], def: "A system that keeps every revision of every file, records who changed what and when, and lets a team return to any earlier state.", ch: "1.3" },
    "vertex": { term: "Vertex", aka: ["vertices","vert"], def: "One corner of a mesh together with everything stored about it: position, normal, UVs and more.", ch: "4.1" },
    "vertex-animation": { term: "Vertex animation", aka: ["vertex shader animation","World Position Offset","WPO","vertex offset","vertex displacement"], def: "Moving a mesh's vertices in the vertex shader every frame, for effects such as foliage swaying in the wind or a flag rippling, with no skeleton and no work on the CPU.", ch: "5.2" },
    "vertex-animation-texture": { term: "Vertex animation texture", aka: ["VAT","baked vertex animation","AnimToTexture"], def: "Animation baked into a texture: each texel holds one vertex's position in one frame, and the vertex shader reads the row for the current frame. No skeleton is evaluated at runtime.", ch: "4.6" },
    "vertex-attribute": { term: "Vertex attribute", aka: ["attribute","vertex channel","vertex element"], def: "One piece of data stored per vertex, such as position, normal, UV, colour or bone weights.", ch: "4.2" },
    "vertex-buffer": { term: "Vertex buffer", aka: ["VBO","vertex array"], def: "A block of GPU memory holding a mesh's vertices as rows of numbers, one row per vertex, ready for the GPU to read.", ch: "4.2" },
    "vertex-cache": { term: "Post-transform vertex cache", aka: ["vertex cache","post-transform cache"], def: "A small GPU cache of recently processed vertices. When an index repeats soon after, the GPU reuses the result instead of running the vertex shader again.", ch: "4.2" },
    "vertex-colour": { term: "Vertex colour", aka: ["vertex color","vertex paint","COLOR_0"], def: "A colour, or four numbers, stored at each vertex and blended across the triangles between. Games use it as a cheap mask for dirt, material blending, wind strength and similar effects.", ch: "4.1" },
    "vertex-layout": { term: "Vertex layout", aka: ["input layout","vertex declaration","vertex format","vertex descriptor"], def: "The description that tells the GPU how to read a vertex buffer: which attributes it holds, their formats, and their byte offsets inside each row.", ch: "4.2" },
    "vertex-shader": { term: "Vertex shader", aka: [], def: "The GPU program that runs once per vertex, typically to move it from the model's own coordinates to its place on screen.", ch: "5.2" },
    "vertex-stream": { term: "Vertex stream", aka: ["separate streams","structure of arrays","SoA"], def: "One of several vertex buffers that together describe a mesh, each holding some of the attributes, such as positions in one buffer and everything else in another.", ch: "4.2" },
    "vertical-blank": { term: "Vertical blank", aka: ["vblank","vertical blanking interval","VBI"], def: "The short pause after a display has drawn its bottom row and before it starts again at the top. Swapping frames during it causes no tearing.", ch: "3.1" },
    "vertical-slice": { term: "Vertical slice", aka: ["slice"], def: "A small part of a game, such as one level, built to final quality in every layer and running on the target hardware. It proves the game and gives the cost of building the rest.", ch: "1.1" },
    "vfx-artist": { term: "VFX artist", aka: ["effects artist","FX artist"], def: "An artist who creates visual effects such as fire, smoke, magic, impacts and weather, usually with particle systems and custom materials.", ch: "1.2" },
    "view-matrix": { term: "View matrix", aka: ["camera matrix","world-to-view matrix","world-to-camera matrix","V"], def: "The matrix that moves the whole world into view space so the camera sits at the origin. It is the inverse of the camera's own transform.", ch: "3.4" },
    "view-space": { term: "View space", aka: ["camera space","eye space"], def: "Coordinates measured from the camera: the camera sits at the origin and looks straight along one axis. Some lighting and depth calculations are done here.", ch: "3.4" },
    "vignette": { term: "Vignette", aka: ["vignetting"], def: "Darkening towards the corners of the image, as many lenses do, used to draw the eye to the centre.", ch: "9.4" },
    "virtual-shadow-maps": { term: "Virtual shadow maps", aka: ["VSM","VSMs","paged shadow maps"], def: "Very large shadow maps, 16,384 texels square in Unreal Engine 5, cut into pages that are allocated, rendered and cached only where on-screen pixels need them.", ch: "7.5" },
    "virtual-texturing": { term: "Virtual texturing", aka: ["SVT","streaming virtual texturing","runtime virtual texturing","megatexture"], def: "Cutting textures into small pages and loading only the pages visible pixels use into a fixed cache, with a page table telling the shader where each page is. Memory stays nearly constant however large the textures are.", ch: "6.3" },
    "visibility-buffer": { term: "Visibility buffer", aka: ["vis buffer","VisBuffer"], def: "A screen buffer that stores only which triangle covers each pixel, in as few as 4 bytes. A later pass looks the triangle up, rebuilds the surface and runs the material for visible pixels only.", ch: "7.3" },
    "volumetric-clouds": { term: "Volumetric clouds", aka: ["Volumetric Cloud","Volumetric Clouds","ray-marched clouds","Nubis"], def: "Clouds rendered by ray marching a 3D density field, usually built from tiling noise shaped by a weather map, between two altitudes. Lit by sun samples taken along the way, they change with the time of day and can be flown through.", ch: "9.5" },
    "volumetric-fog": { term: "Volumetric fog", aka: ["volumetric lighting","Volumetric Fog","volumetric scattering"], def: "Fog computed in a 3D grid that fills the view, so its density can vary from place to place and every light, with its shadows, can light it. It produces light shafts and lit haze around lamps that height fog cannot.", ch: "9.5" },
    "voxel-cone-tracing": { term: "Voxel cone tracing", aka: ["VCT","VXGI","SVOGI","sparse voxel octree global illumination"], def: "Real-time GI that stores the scene's lit surfaces in voxels with blurred, coarser copies, then gathers light along a few cones per pixel, reading coarser voxels as each cone widens.", ch: "8.5" },
    "voxelgi": { term: "VoxelGI", aka: ["VoxelGI node"], def: "Godot's voxel-based GI node. It voxelizes static geometry inside a box in a bake of seconds, then lights it in real time, so lights can move and change; Forward+ renderer only.", ch: "8.5" },
    "vr-reprojection": { term: "Reprojection (VR)", aka: ["reprojection","TimeWarp","SpaceWarp","Application SpaceWarp","AppSW"], def: "A headset reusing or synthesising frames when the game's frame is late or deliberately rendered at half rate, warping images to the latest head position so the world stays steady.", ch: "1.4" },
    "vram": { term: "VRAM", aka: ["video RAM","video memory","GPU memory"], def: "The GPU's own memory. Meshes and textures live here so the GPU can read them fast without asking the CPU.", ch: "3.5" },
    "vram-overcommit": { term: "VRAM over-commit", aka: ["VRAM oversubscription","over the VRAM budget","memory oversubscription","paging to system memory"], def: "A PC game using more GPU memory than its budget. Windows may freeze it at times or leave resources in slower system memory, so frames slow down for as long as it stays over.", ch: "11.4" },
    "vrr": { term: "Variable refresh rate", aka: ["VRR","G-SYNC","FreeSync","Adaptive-Sync","HDMI VRR"], def: "A display mode in which the screen waits for each new frame and refreshes when it arrives, within a range such as 48 to 144 Hz. It removes tearing without the stutter of vsync.", ch: "3.1" },
    "vrs": { term: "Variable rate shading", aka: ["VRS","coarse pixel shading","shading rate image","fragment shading rate"], def: "A GPU feature that runs the pixel shader once for a block of pixels, such as 2 by 2, in chosen parts of the screen, while depth and coverage stay at full resolution.", ch: "9.3" },
    "vsync": { term: "Vsync", aka: ["V-Sync","vertical sync","vertical synchronisation"], def: "Holding each finished frame until the display's vertical blank before swapping it in. It removes tearing but adds waiting, and uneven waits show as stutter.", ch: "3.1" },
    "vulkan": { term: "Vulkan", aka: [], def: "The Khronos Group's cross-platform explicit graphics API. It is the main API on Android and Linux, including the Steam Deck, and also runs on Windows and Nintendo Switch.", ch: "3.5" },
    "vulkan-ray-tracing": { term: "Vulkan ray tracing", aka: ["VK_KHR_ray_tracing_pipeline","VK_KHR_acceleration_structure","VK_KHR_ray_query"], def: "The Khronos extensions, final since November 2020, that add acceleration structures, ray tracing pipelines and ray queries to Vulkan.", ch: "8.6" },
    "warp": { term: "Warp", aka: ["wavefront","wave","subgroup","SIMD-group"], def: "A group of GPU lanes that run the same instruction together: 32 lanes on NVIDIA GPUs, 32 or 64 on AMD's. When lanes in one warp take different branches, the warp runs both.", ch: "3.5" },
    "webgpu": { term: "WebGPU", aka: [], def: "The modern graphics API for web browsers and the successor to WebGL. Chrome, Edge, Firefox and Safari ship it, though not yet on every operating system.", ch: "3.5" },
    "white-balance": { term: "White balance", aka: ["Temperature and Tint","Temp and Tint","white point"], def: "Shifting colours so that a chosen light reads as neutral white, removing a warm or cool cast, as cameras do. Engines expose it as temperature and tint controls.", ch: "9.1" },
    "winding-order": { term: "Winding order", aka: ["front face","CW","clockwise","CCW","counter-clockwise"], def: "Whether a triangle's corners go clockwise or anticlockwise on screen. The GPU uses it to decide which side of the triangle is the front.", ch: "4.1" },
    "world-partition": { term: "World Partition", aka: ["runtime grid","streaming grid","World Partition grid"], def: "Unreal Engine's open-world system: the world is divided into grid cells that are loaded and unloaded automatically around streaming sources such as the player.", ch: "11.4" },
    "world-space": { term: "World space", aka: ["global space","scene space"], def: "The single coordinate space shared by the whole level, in which every object, light and camera has a position.", ch: "3.4" },
    "world-transform": { term: "World transform", aka: ["global transform","global_position","world location"], def: "An object's position, rotation and scale measured from the world's origin, found by combining its local transform with every parent above it.", ch: "2.3" },
    "wrap-mode": { term: "Wrap mode", aka: ["address mode","tiling method","repeat","clamp","mirror"], def: "What the GPU does with UV coordinates outside 0 to 1: repeat the texture, clamp to its edge texels, or mirror it on every repeat.", ch: "6.1" },
    "xess": { term: "XeSS", aka: ["Intel Xe Super Sampling","XeSS-SR","XeSS-FG","XeLL","Xe Low Latency"], def: "Intel's machine-learned temporal upscaler, using the matrix units of Arc GPUs with a cross-vendor fallback, plus XeSS Frame Generation and the Xe Low Latency mode it requires.", ch: "9.3" },
    "z-fighting": { term: "Z-fighting", aka: ["depth fighting","z-fight"], def: "Flickering stripes where two surfaces closer together than one step of stored depth show through each other, because rounding rather than distance decides which is in front.", ch: "5.5" }
  };
})();
